const games=[
{id:1,title:"Las cuatro esquinas",cycle:"1.º ciclo",goals:["Velocidad","Percepción espacial"],material:"Conos",intensity:"Alta",duration:10,group:"5 por zona",color:"orange",summary:"Cambios rápidos de lugar mientras una persona intenta ocupar una esquina libre.",setup:"Marca cuadrados de 6 × 6 metros con cuatro conos. En cada cuadrado juegan cinco participantes: cuatro ocupan las esquinas y uno se coloca en el centro.",rules:["A una señal, quienes están en las esquinas deben intercambiar su posición.","La persona del centro trata de ocupar una esquina libre.","Quien se quede sin esquina pasa al centro. No vale permanecer dos rondas seguidas sin cambiar."],variant:"Añade una segunda persona en el centro o permite cambios solo con desplazamientos indicados: lateral, saltos o cuadrupedia.",safety:"Deja al menos dos metros entre cuadrados y recuerda mirar antes de cruzar."},
{id:2,title:"El pañuelo cooperativo",cycle:"2.º ciclo",goals:["Cooperación","Velocidad"],material:"Sin material",intensity:"Alta",duration:15,group:"2 equipos",color:"blue",summary:"Una versión sin eliminación en la que cada carrera exige colaborar con compañeros diferentes.",setup:"Forma dos equipos numerados a ambos lados de una línea central. La persona docente sostiene un peto o pañuelo.",rules:["Al nombrar uno o varios números, salen esos participantes.","Si salen varios, deben llegar unidos de la forma indicada.","Consiguen un punto llevando el pañuelo a su campo sin ser tocados."],variant:"Nombra operaciones sencillas en lugar de números o exige transportar el pañuelo sin usar las manos.",safety:"Sitúa las líneas de salida lejos de paredes y evita tirones del pañuelo."},
{id:3,title:"Islas y tiburones",cycle:"1.º ciclo",goals:["Equilibrio","Cooperación"],material:"Aros",intensity:"Media",duration:12,group:"Gran grupo",color:"green",summary:"El grupo se desplaza por el espacio y busca refugio compartiendo islas cada vez más pequeñas.",setup:"Reparte aros por el espacio. Debe haber al principio suficientes para que entren dos o tres personas en cada uno.",rules:["Mientras suena una palmada rítmica, todos se desplazan sin pisar las islas.","Al grito de «¡tiburones!», deben refugiarse dentro de un aro.","En cada ronda se retira un aro. Nadie queda eliminado: el reto es que todo el grupo encuentre sitio."],variant:"Cambia la forma de desplazarse o pide que en cada isla haya un número exacto de apoyos.",safety:"Los aros deben estar planos y suficientemente separados para evitar choques."},
{id:4,title:"Balón torre",cycle:"3.º ciclo",goals:["Lanzamientos","Juego colectivo"],material:"Balones",intensity:"Alta",duration:20,group:"2 equipos",color:"yellow",summary:"Juego de invasión en el que se puntúa conectando un pase con el compañero situado en la torre.",setup:"Delimita un campo rectangular y una zona de torre en cada fondo. Un jugador de cada equipo ocupa la zona contraria sobre una colchoneta o dentro de un aro.",rules:["Se avanza mediante pases; con balón en las manos solo se permiten tres pasos.","Se logra un punto si el jugador torre recibe sin salir de su zona.","No se puede arrebatar el balón de las manos ni entrar en las zonas de torre."],variant:"Cambia de torre después de cada punto o exige que todos toquen el balón antes de marcar.",safety:"Utiliza un balón blando y prohíbe el contacto corporal."},
{id:5,title:"El espejo viajero",cycle:"1.º ciclo",goals:["Expresión corporal","Coordinación"],material:"Sin material",intensity:"Baja",duration:8,group:"Parejas",color:"blue",summary:"Por parejas, una persona crea movimientos y la otra reproduce su reflejo mientras avanzan.",setup:"Distribuye las parejas por todo el espacio, frente a frente y con suficiente separación respecto a las demás.",rules:["Una persona guía con movimientos lentos y continuos.","Su pareja imita como si fuera su reflejo.","A la señal cambian los roles; después pueden desplazarse juntos."],variant:"Realiza el juego con música, emociones o movimientos propios de distintos deportes.",safety:"Comienza sin desplazamiento y limita los movimientos bruscos o de gran amplitud."},
{id:6,title:"Robar colas",cycle:"2.º ciclo",goals:["Agilidad","Estrategia"],material:"Conos",intensity:"Alta",duration:10,group:"Individual",color:"orange",summary:"Cada participante protege su cola mientras intenta capturar las de los demás.",setup:"Cada jugador coloca un peto o cinta en la cintura, visible y fácil de extraer. Delimita un campo amplio.",rules:["A la señal todos intentan coger colas sin perder la suya.","Las colas capturadas se llevan en la mano, nunca se colocan en la cintura.","Si alguien pierde su cola, sigue jugando y puede conseguir otra. Gana quien acumula más."],variant:"Juega por equipos: las colas capturadas se llevan a una base común.",safety:"No permitas agarrar ropa ni bloquear con los brazos; usa cintas que salgan fácilmente."},
{id:7,title:"Cruzar el río",cycle:"2.º ciclo",goals:["Resolución de problemas","Cooperación"],material:"Aros",intensity:"Media",duration:15,group:"Equipos de 5",color:"green",summary:"Cada equipo debe atravesar una zona sin tocar el suelo usando menos apoyos que personas.",setup:"Marca dos orillas separadas 10–12 metros. Entrega a cada equipo tres o cuatro aros.",rules:["Todo el equipo debe llegar a la otra orilla sin tocar el suelo fuera de los aros.","Los aros no pueden lanzarse; deben pasarse de mano en mano.","Si alguien toca el río, el grupo vuelve al último punto seguro."],variant:"Transporta además una pelota que no puede tocar el suelo o retira un aro a mitad del recorrido.",safety:"Evita saltos largos y utiliza superficies que no resbalen."},
{id:8,title:"Cazadores de colores",cycle:"1.º ciclo",goals:["Reacción","Percepción espacial"],material:"Conos",intensity:"Media",duration:10,group:"Gran grupo",color:"yellow",summary:"Una respuesta motriz rápida a consignas de color distribuidas por todo el espacio.",setup:"Coloca conos de cuatro colores en las esquinas y en algunos puntos centrales.",rules:["El grupo se desplaza libremente siguiendo la consigna motriz.","Al nombrar un color, deben tocar un cono de ese color y continuar.","No pueden acudir dos veces seguidas al mismo cono."],variant:"Relaciona cada color con una acción, un número de apoyos o una agrupación.",safety:"Reparte varios conos de cada color para que no se produzcan aglomeraciones."},
{id:9,title:"Los diez pases",cycle:"3.º ciclo",goals:["Pases","Desmarque"],material:"Balones",intensity:"Alta",duration:18,group:"2 equipos",color:"blue",summary:"Conservar la posesión y sumar diez pases ante la oposición de otro equipo.",setup:"Forma equipos reducidos de cuatro a seis y delimita campos proporcionados. Usa un balón por campo.",rules:["Cada pase completado suma uno; al llegar a diez se consigue punto.","Si cae, sale o lo interceptan, la cuenta vuelve a cero y cambia la posesión.","No se permite desplazarse con el balón ni el contacto."],variant:"Añade comodines exteriores o limita el tiempo de posesión a tres segundos.",safety:"Evita balones duros y ajusta el espacio para que no haya choques entre campos."},
{id:10,title:"Semáforo en movimiento",cycle:"1.º ciclo",goals:["Control corporal","Atención"],material:"Sin material",intensity:"Media",duration:8,group:"Gran grupo",color:"green",summary:"Desplazarse, frenar y regular la velocidad respondiendo a señales visuales o verbales.",setup:"Todo el grupo se coloca tras una línea. La meta está a unos quince metros.",rules:["Verde significa avanzar, amarillo moverse muy despacio y rojo quedarse inmóvil.","Quien se mueve en rojo retrocede tres pasos, sin quedar eliminado.","La ronda termina cuando todo el grupo alcanza la meta."],variant:"Añade azul para desplazamiento lateral y blanco para realizar un equilibrio.",safety:"Deja una zona amplia de frenado y evita carreras máximas si el suelo resbala."},
{id:11,title:"La telaraña",cycle:"3.º ciclo",goals:["Cooperación","Habilidades motrices"],material:"Cuerdas",intensity:"Baja",duration:20,group:"Equipos de 8",color:"orange",summary:"El equipo atraviesa huecos de una telaraña sin tocar las cuerdas y usando cada hueco una sola vez.",setup:"Construye una red con cuerdas entre dos soportes seguros, dejando huecos de distintos tamaños a poca altura.",rules:["Cada integrante debe pasar por un hueco diferente.","El equipo puede ayudar, pero nadie puede tocar las cuerdas.","Si hay contacto, se repite el paso con un hueco disponible."],variant:"Sin telaraña física, crea huecos verticales con aros sostenidos de forma segura.",safety:"No uses huecos altos; queda prohibido levantar a nadie por encima de la cintura."},
{id:12,title:"Relevos de animales",cycle:"1.º ciclo",goals:["Desplazamientos","Coordinación"],material:"Conos",intensity:"Alta",duration:12,group:"Equipos de 5",color:"yellow",summary:"Relevos no competitivos con desplazamientos inspirados en animales.",setup:"Prepara calles cortas de ida y vuelta, cada una señalizada con un cono.",rules:["El primero recorre la calle con el desplazamiento indicado y da el relevo con la mano.","Cada ronda usa un animal diferente.","El reto es completar el recorrido con técnica y control, no solo con velocidad."],variant:"Deja que cada equipo invente un animal y enseñe su desplazamiento al resto.",safety:"Evita recorridos largos en cuadrupedia y separa bien las calles."},
{id:13,title:"Derriba el castillo",cycle:"2.º ciclo",goals:["Puntería","Lanzamientos"],material:"Balones",intensity:"Media",duration:15,group:"Equipos de 4",color:"orange",summary:"Lanzamientos de precisión para derribar una construcción de conos desde diferentes distancias.",setup:"Construye pequeños castillos de conos. Marca líneas de lanzamiento a tres, cinco y siete metros.",rules:["Cada jugador dispone de un lanzamiento antes de rotar.","Cada cono derribado suma un punto y se reconstruye el castillo.","La línea lejana puntúa doble. Solo se recoge cuando todos han lanzado."],variant:"Lanza con la mano no dominante, rodando o después de un pase de un compañero.",safety:"Todas las recogidas se hacen a la vez y solo tras la señal docente."},
{id:14,title:"Guardianes del tesoro",cycle:"3.º ciclo",goals:["Estrategia","Velocidad"],material:"Balones",intensity:"Alta",duration:18,group:"3 equipos",color:"green",summary:"Atacantes y guardianes gestionan riesgos para recuperar objetos del centro.",setup:"Coloca veinte pelotas u objetos blandos en un círculo central. Dos equipos parten desde bases opuestas y un tercero protege el tesoro.",rules:["Los atacantes pueden llevar un solo tesoro por viaje.","Si un guardián toca a un atacante dentro de la zona, este devuelve el objeto y regresa a su base.","Tras dos minutos se rotan los papeles."],variant:"Crea objetos con distinto valor o permite rescates cooperativos por parejas.",safety:"Los guardianes tocan suavemente con una mano; no pueden bloquear físicamente."},
{id:15,title:"Nudos humanos",cycle:"2.º ciclo",goals:["Cooperación","Expresión corporal"],material:"Sin material",intensity:"Baja",duration:10,group:"Equipos de 8",color:"blue",summary:"Resolver en grupo un nudo formado con las manos sin romper la cadena.",setup:"En círculos de seis a ocho, todos extienden las manos hacia el centro y toman dos manos distintas.",rules:["Sin soltarse, deben desenredarse hasta formar uno o varios círculos.","Pueden hablar y decidir el orden de los movimientos.","Si una postura molesta, se detiene el juego y se reajusta el agarre."],variant:"Hazlo primero con grupos de cuatro o resuélvelo en silencio.",safety:"Agarres suaves; nada de torsiones forzadas ni pasar por encima de otras personas."},
{id:16,title:"La cadena",cycle:"2.º ciclo",goals:["Velocidad","Cooperación"],material:"Sin material",intensity:"Alta",duration:12,group:"Gran grupo",color:"yellow",summary:"Quienes pillan van formando una cadena que necesita coordinarse para seguir creciendo.",setup:"Delimita un espacio sin obstáculos. Una persona comienza persiguiendo.",rules:["Al tocar a alguien, ambos se dan la mano y continúan juntos.","Cuando la cadena llega a cuatro, se divide en dos parejas.","Solo pueden tocar quienes ocupan los extremos de la cadena."],variant:"No dividir la cadena y comprobar hasta qué tamaño puede coordinarse.",safety:"Prohíbe tirones y cambios bruscos de dirección; si se sueltan, deben detenerse."},
{id:17,title:"Bolos viajeros",cycle:"3.º ciclo",goals:["Puntería","Cálculo mental"],material:"Balones",intensity:"Baja",duration:15,group:"Parejas",color:"orange",summary:"Un desafío de precisión por estaciones en el que cada distancia modifica la puntuación.",setup:"Coloca botellas o conos como bolos y tres líneas de tiro. Cada pareja dispone de una pelota blanda.",rules:["Se lanza rodando desde una de las tres líneas.","Los bolos derribados se multiplican por el valor de la línea: ×1, ×2 o ×3.","Después de tres turnos, la pareja cambia de estación."],variant:"Cada pareja diseña una disposición de bolos y calcula su puntuación máxima posible.",safety:"Las pelotas se recogen únicamente cuando la zona queda sin lanzadores."},
{id:18,title:"Figuras en equipo",cycle:"1.º ciclo",goals:["Expresión corporal","Cooperación"],material:"Sin material",intensity:"Baja",duration:10,group:"Equipos de 5",color:"green",summary:"Crear con el cuerpo figuras, letras y escenas sencillas antes de que termine la cuenta atrás.",setup:"Distribuye pequeños equipos por zonas separadas. Prepara una lista de palabras o imágenes conocidas.",rules:["Al escuchar la consigna, cada equipo tiene veinte segundos para crearla con sus cuerpos.","Todos deben participar y la figura debe mantenerse cinco segundos.","El resto intenta adivinar antes de mostrar una nueva consigna."],variant:"Representa letras, números, deportes, medios de transporte o contenidos de otras áreas.",safety:"Todas las figuras se realizan de pie, sentados o tumbados, sin cargar peso sobre compañeros."}
];

games.forEach(g=>g.type="Juego motor");
games.push(
{id:19,type:"Deporte alternativo",title:"Colpbol",cycle:"2.º ciclo",goals:["Cooperación","Golpeo"],material:"Balones",intensity:"Alta",duration:25,group:"2 equipos",color:"orange",summary:"Deporte colectivo de invasión en el que el balón se juega con un solo golpe y nadie puede retenerlo.",setup:"Usa una pista con dos porterías, un balón ligero y equipos mixtos de cinco a siete jugadores. Para iniciación, reduce el campo.",rules:["El balón se impulsa con manos, brazos o parte superior del cuerpo, sin agarrarlo.","Cada participante solo puede dar un golpe consecutivo; necesita apoyarse en el equipo.","Se marca enviando el balón a la portería contraria. No hay contacto ni golpeo intencionado con el pie."],variant:"Comienza con zonas de gol amplias y permite un bote antes de cada golpe.",safety:"Utiliza balón blando, evita golpeos cerca de la cara y prohíbe cualquier contacto corporal."},
{id:20,type:"Deporte alternativo",title:"Ultimate escolar",cycle:"3.º ciclo",goals:["Lanzamientos","Desmarque"],material:"Disco volador",intensity:"Alta",duration:25,group:"2 equipos",color:"blue",summary:"Deporte autoarbitrado de pase y recepción con disco, sin contacto y basado en el juego limpio.",setup:"Marca un campo rectangular con una zona de marca en cada fondo. Forma equipos de cinco y utiliza un disco blando.",rules:["Quien recibe el disco se detiene y dispone de diez segundos para pasarlo.","La posesión cambia si el disco cae, sale o es interceptado.","Hay punto cuando un compañero recibe dentro de la zona de marca rival. No se permite correr con el disco ni el contacto."],variant:"Para iniciación, permite recoger el disco tras un bote o utiliza una pelota antes de introducir el disco.",safety:"Mantén distancia defensiva, evita lanzamientos fuertes a corta distancia y usa discos flexibles."},
{id:21,type:"Deporte alternativo",title:"Tchoukball",cycle:"3.º ciclo",goals:["Lanzamientos","Anticipación"],material:"Material específico",intensity:"Alta",duration:25,group:"2 equipos",color:"green",summary:"Juego de lanzamiento contra una superficie de rebote en el que la defensa anticipa sin bloquear al atacante.",setup:"Coloca un cuadro de rebote en cada fondo y marca un semicírculo prohibido delante. Forma dos equipos de cinco a siete.",rules:["Se puede atacar cualquiera de los dos cuadros y realizar hasta tres pases antes del lanzamiento.","Se consigue punto si el balón rebota en el cuadro y toca el suelo fuera de la zona prohibida.","La defensa no intercepta pases ni bloquea; intenta recibir el rebote antes de que caiga."],variant:"En iniciación usa un único cuadro y permite un bote del rebote antes de atraparlo.",safety:"Asegura el cuadro, despeja su parte posterior y no permitas entrar en la zona de caída del lanzador."},
{id:22,type:"Deporte alternativo",title:"Kin-Ball escolar",cycle:"2.º ciclo",goals:["Cooperación","Anticipación"],material:"Material específico",intensity:"Media",duration:25,group:"3 equipos",color:"yellow",summary:"Tres equipos comparten pista y cooperan para golpear y recibir un balón gigante antes de que toque el suelo.",setup:"Forma tres equipos de cuatro con petos de colores y utiliza un balón gigante ligero en un espacio amplio.",rules:["Tres integrantes sujetan el balón y el cuarto lo golpea tras nombrar al equipo receptor.","El equipo nombrado evita que el balón toque el suelo y prepara un nuevo saque.","Todas las personas del equipo deben participar en el golpeo; se puntúa cuando el receptor no controla."],variant:"En iniciación elimina la puntuación y plantea cuántos intercambios seguidos consiguen los tres equipos.",safety:"Balón muy ligero, espacio sin obstáculos y prohibición de golpear hacia abajo o directamente a una persona."},
{id:23,type:"Deporte alternativo",title:"Datchball",cycle:"2.º ciclo",goals:["Lanzamientos","Esquiva"],material:"Balones",intensity:"Alta",duration:20,group:"2 equipos",color:"orange",summary:"Deporte de cancha dividida con balones de espuma, lanzamientos, recepciones y posibilidad de volver al juego.",setup:"Divide el campo en dos mitades. Sitúa tres balones blandos en el centro y dos equipos detrás de sus líneas de fondo.",rules:["A la señal, cada equipo busca los balones de su derecha y lanza desde su propio campo.","Un impacto directo por debajo de los hombros elimina temporalmente; si el rival atrapa el balón al vuelo, sale el lanzador.","Las personas eliminadas regresan en el orden de salida cuando su equipo logra una recepción válida."],variant:"Juega por tiempo y puntúa cada eliminación, sin dejar a nadie fuera más de treinta segundos.",safety:"Solo balones de espuma; los impactos en cabeza no cuentan y se sancionan los lanzamientos fuertes a corta distancia."},
{id:24,type:"Deporte alternativo",title:"Floorball",cycle:"3.º ciclo",goals:["Conducción","Juego colectivo"],material:"Sticks",intensity:"Alta",duration:25,group:"2 equipos",color:"blue",summary:"Modalidad similar al hockey, con sticks ligeros y pelota perforada, adaptada para evitar el contacto.",setup:"Forma equipos de cuatro o cinco, dos porterías pequeñas y sticks de plástico. Empieza sin porteros.",rules:["La pelota se conduce y pasa con ambas caras de la pala por debajo de la rodilla.","Se marca introduciéndola en la portería contraria.","No se levanta el stick, no se golpea el stick rival y no existe contacto corporal."],variant:"Juega tres contra tres en campos pequeños o marca zonas obligatorias de pase antes del tiro.",safety:"Agarre con dos manos, pala siempre baja y distancia de seguridad antes de golpear."},
{id:25,type:"Deporte alternativo",title:"Ringo",cycle:"2.º ciclo",goals:["Lanzamientos","Recepción"],material:"Material específico",intensity:"Media",duration:20,group:"Parejas o equipos",color:"green",summary:"Juego de cancha dividida en el que se lanza y recibe un aro de goma por encima de una red.",setup:"Utiliza una red baja o una cuerda y un aro flexible. Empieza uno contra uno o dos contra dos en campos pequeños.",rules:["El aro se lanza por encima de la red y debe caer dentro del campo contrario.","Se recibe con una mano y se lanza sin cambiarlo de mano ni caminar.","El saque cambia tras cada punto; en dobles se alternan las recepciones."],variant:"Permite recepción con dos manos o un pase entre compañeros antes de devolver el aro.",safety:"Usa aros blandos, deja separación entre pistas y evita lanzamientos dirigidos al cuerpo."},
{id:26,type:"Deporte alternativo",title:"Goubak",cycle:"3.º ciclo",goals:["Pases","Estrategia"],material:"Material específico",intensity:"Alta",duration:25,group:"2 equipos",color:"yellow",summary:"Deporte mixto de invasión alrededor de una portería central, con balón especial y puntuación por valores.",setup:"Coloca una portería de tres planos en el centro de un campo circular. Dos equipos de cinco comparten todo el espacio.",rules:["El equipo atacante dispone de cinco pases para lanzar atravesando la portería central.","Un compañero debe recibir al otro lado para validar la jugada.","La puntuación depende de la zona desde la que se lanza y del tipo de recepción; tras puntuar cambia la posesión."],variant:"Usa una portería central improvisada y concede un punto fijo a todas las recepciones válidas.",safety:"Prohíbe el contacto y delimita una zona de seguridad alrededor de la portería."},
{id:27,type:"Deporte alternativo",title:"Tripela",cycle:"3.º ciclo",goals:["Coordinación óculo-pédica","Juego colectivo"],material:"Balones",intensity:"Alta",duration:25,group:"2 equipos",color:"orange",summary:"Deporte de invasión que combina el juego con el pie y la recepción con las manos.",setup:"En una pista con porterías, forma equipos de cinco. Utiliza un balón de fútbol blando o de tamaño reducido.",rules:["El balón se impulsa con el pie, pero se recibe con las manos antes de volver a jugarlo.","No se puede correr con el balón controlado; hay que pasar en pocos segundos.","Se consigue gol mediante lanzamiento con el pie, respetando la zona de portería adaptada."],variant:"Permite que el balón bote antes de la recepción o exige un número mínimo de pases.",safety:"Balón blando, tiros por debajo de la cintura en iniciación y ausencia total de contacto."},
{id:28,type:"Deporte alternativo",title:"Bijbol",cycle:"2.º ciclo",goals:["Cooperación","Lanzamientos"],material:"Material específico",intensity:"Media",duration:20,group:"2 equipos",color:"blue",summary:"Juego colectivo con pelota gigante en el que se progresa mediante golpes hasta alcanzar la zona de gol.",setup:"Delimita un campo con dos zonas de marca y utiliza una pelota gigante ligera. Forma equipos de seis a ocho.",rules:["El balón avanza mediante golpes con cualquier parte del cuerpo, sin agarrarlo.","Cada jugador solo puede golpear una vez seguida.","Se marca cuando el balón cruza la línea de fondo rival; no se puede empujar ni bloquear a otras personas."],variant:"Puntúa por completar pases entre todos antes de cruzar la línea, sin oposición al principio.",safety:"Usa balón ligero, evita amontonamientos debajo de él y detén el juego si sale de la zona segura."},
{id:29,type:"Deporte alternativo",title:"Pickleball adaptado",cycle:"3.º ciclo",goals:["Golpeo","Percepción espacial"],material:"Material específico",intensity:"Media",duration:25,group:"Parejas",color:"green",summary:"Deporte de pala y red de aprendizaje rápido, presentado con reglas simplificadas para el entorno escolar.",setup:"Monta pistas pequeñas con red baja o cinta. Utiliza palas cortas y pelotas perforadas o de espuma.",rules:["El saque se realiza por debajo de la cintura y en diagonal.","Antes de volear, la pelota debe botar una vez en cada campo tras el saque.","Se juega hasta once puntos; en iniciación puede puntuar cada jugada y se permite un bote adicional."],variant:"Empieza sin red, cooperando por parejas para mantener el mayor número de intercambios.",safety:"Deja pasillos entre pistas y comprueba que nadie entre en el radio de movimiento de las palas."},
{id:30,type:"Deporte alternativo",title:"Artziki escolar",cycle:"3.º ciclo",goals:["Juego colectivo","Coordinación"],material:"Balones",intensity:"Alta",duration:25,group:"2 equipos",color:"yellow",summary:"Deporte que mezcla recursos del balonmano, fútbol y rugby en un juego de invasión dinámico.",setup:"Utiliza un campo rectangular con dos porterías y equipos de cinco o seis. Balón blando de tamaño medio.",rules:["El balón puede jugarse con manos o pies; con las manos no se puede avanzar libremente.","Los pases pueden hacerse en cualquier dirección y el objetivo es marcar en la portería rival.","No se permite el contacto, arrebatar el balón de las manos ni retenerlo más de cinco segundos."],variant:"Divide el campo en zonas y exige alternar un pase con la mano y otro con el pie.",safety:"Sin placajes ni contacto; limita la potencia de los tiros y usa porterías estables."}
);
const imageFiles=["01-las-cuatro-esquinas.webp","02-panuelo-cooperativo.webp","03-islas-tiburones.webp","04-balon-torre.webp","05-espejo-viajero.webp","06-robar-colas.webp","07-cruzar-rio.webp","08-cazadores-colores.webp","09-diez-pases.webp","10-semaforo.webp","11-telarana.webp","12-relevos-animales.webp","13-derriba-castillo.webp","14-guardianes-tesoro.webp","15-nudos-humanos.webp","16-la-cadena.webp","17-bolos-viajeros.webp","18-figuras-equipo.webp","19-colpbol.webp","20-ultimate.webp","21-tchoukball.webp","22-kin-ball.webp","23-datchball.webp","24-floorball.webp","25-ringo.webp","26-goubak.webp","27-tripela.webp","28-bijbol.webp","29-pickleball.webp","30-artziki.webp"];
games.forEach((g,i)=>g.image=`images/games/${imageFiles[i]}`);
games.push(
{id:31,type:"Juego cooperativo",title:"El paracaídas viajero",cycle:"1.º ciclo",goals:["Cooperación","Coordinación"],material:"Material específico",intensity:"Media",duration:12,group:"Equipos de 8",color:"green",summary:"El equipo transporta una pelota sobre un paracaídas coordinando altura, ritmo y desplazamiento.",setup:"Cada grupo rodea un paracaídas o sábana resistente y sujeta el borde con ambas manos. Coloca una pelota ligera en el centro.",rules:["El grupo debe recorrer un circuito corto sin que la pelota caiga.","Todos mantienen su posición alrededor de la tela y adaptan juntos la tensión.","Si cae, se recoge y se continúa desde el último cono, sin penalización."],variant:"Transporta dos pelotas, cambia el sentido de marcha o crea olas suaves al llegar a cada cono.",safety:"Usa pelotas ligeras, camina en lugar de correr y mantén despejado el recorrido."},
{id:32,type:"Juego cooperativo",title:"La oruga cooperativa",cycle:"1.º ciclo",goals:["Cooperación","Coordinación"],material:"Conos",intensity:"Baja",duration:10,group:"Equipos de 6",color:"orange",summary:"Avanzar como una sola oruga exige acordar el ritmo y ayudar a que nadie quede atrás.",setup:"Forma filas de cinco o seis participantes sentados, con piernas separadas y manos apoyadas suavemente en los hombros de quien está delante.",rules:["La oruga avanza hasta un cono sin separar sus segmentos.","El grupo decide una señal para mover ambos lados de forma coordinada.","Si se rompe, se detiene, vuelve a unirse y continúa."],variant:"Realiza un recorrido curvo o transporta una pelota pequeña de la cabeza a la cola.",safety:"Recorrido corto sobre superficie limpia; sin tirones, carreras ni empujones."},
{id:33,type:"Juego cooperativo",title:"La alfombra mágica",cycle:"2.º ciclo",goals:["Resolución de problemas","Equilibrio"],material:"Material específico",intensity:"Baja",duration:12,group:"Equipos de 5",color:"blue",summary:"El grupo intenta dar la vuelta a una colchoneta sin que ninguna persona toque el suelo.",setup:"Cada equipo se coloca sobre una colchoneta fina o lona resistente con espacio suficiente para todos.",rules:["Deben voltear completamente la alfombra permaneciendo siempre encima.","Pueden hablar, cambiar de posición y ayudarse con las manos.","Si alguien toca el suelo, analizan qué ha ocurrido y vuelven a intentarlo."],variant:"Reduce el tamaño de la alfombra o realiza el reto sin hablar después de una ronda de planificación.",safety:"Usa material antideslizante, sin levantar a compañeros ni pisar manos."},
{id:34,type:"Juego cooperativo",title:"El aro viajero",cycle:"1.º ciclo",goals:["Cooperación","Movilidad corporal"],material:"Aros",intensity:"Baja",duration:10,group:"Equipos de 8",color:"yellow",summary:"Un aro recorre un círculo de personas enlazadas sin que nadie suelte las manos.",setup:"Forma círculos de seis a diez participantes tomados de las manos. Introduce un aro entre dos personas antes de cerrar el círculo.",rules:["El aro debe completar una vuelta pasando alrededor del cuerpo de cada participante.","Las manos permanecen unidas durante todo el recorrido.","El reto termina cuando vuelve al punto inicial; se valora la ayuda y la comunicación."],variant:"Introduce dos aros que viajen en sentidos contrarios o cambia el tamaño del círculo.",safety:"Usa aros grandes y flexibles; movimientos suaves, sin forzar brazos ni cuello."},
{id:35,type:"Juego cooperativo",title:"Transporte del tesoro",cycle:"1.º ciclo",goals:["Cooperación","Control de objetos"],material:"Balones",intensity:"Media",duration:12,group:"Equipos de 6",color:"green",summary:"Transportar varios objetos sobre una tela obliga a repartir fuerzas y anticipar los giros.",setup:"Entrega a cada equipo una sábana pequeña o tela fuerte y coloca encima cuatro pelotas blandas. Prepara un circuito de conos.",rules:["Todos sujetan la tela y recorren juntos el circuito.","No se pueden tocar directamente los tesoros con las manos durante el trayecto.","Si cae una pelota, el grupo se detiene, la recoloca y continúa."],variant:"Añade objetos de distintos tamaños o permite que una persona guíe al equipo desde fuera.",safety:"Caminar, sujetar con ambas manos y mantener distancia entre recorridos."},
{id:36,type:"Juego cooperativo",title:"La pelota que no cae",cycle:"2.º ciclo",goals:["Cooperación","Golpeo"],material:"Balones",intensity:"Media",duration:10,group:"Equipos de 6",color:"orange",summary:"Todo el grupo suma golpeos para mantener una pelota ligera en el aire el mayor tiempo posible.",setup:"Cada equipo ocupa una zona amplia con un globo resistente o pelota muy ligera.",rules:["La pelota no puede tocar el suelo y nadie puede golpearla dos veces seguidas.","Antes de contar un nuevo récord deben participar todos los miembros.","El objetivo es superar la mejor marca del propio equipo, no la de los demás."],variant:"Usa dos pelotas o limita cada golpe a una parte del cuerpo diferente.",safety:"Mira alrededor antes de desplazarte y separa ampliamente las zonas de cada grupo."},
{id:37,type:"Juego cooperativo",title:"El laberinto guiado",cycle:"2.º ciclo",goals:["Confianza","Comunicación"],material:"Conos",intensity:"Baja",duration:15,group:"Parejas",color:"blue",summary:"Una persona guía con la voz a su pareja por un recorrido sencillo, construyendo confianza y escucha.",setup:"Crea pasillos amplios con conos. En cada pareja, una persona lleva los ojos semicubiertos y la otra guía desde fuera del recorrido.",rules:["La guía utiliza únicamente indicaciones verbales claras y tranquilas.","Quien recorre avanza caminando y puede detenerse cuando lo necesite.","Al terminar cambian los roles y comentan qué indicaciones ayudaron más."],variant:"Sin cubrir los ojos, realiza primero el recorrido caminando hacia atrás para aprender las consignas.",safety:"Recorrido sin obstáculos duros, guía siempre cerca y parada inmediata ante cualquier inseguridad."},
{id:38,type:"Juego cooperativo",title:"Puentes sobre el río",cycle:"2.º ciclo",goals:["Resolución de problemas","Cooperación"],material:"Aros",intensity:"Media",duration:15,group:"Equipos de 6",color:"yellow",summary:"El equipo crea y desplaza sus propios puentes para cruzar una zona sin tocar el río.",setup:"Marca dos orillas y entrega a cada equipo dos colchonetas pequeñas y dos aros como apoyos.",rules:["Todo el equipo y todo el material deben llegar a la otra orilla.","Solo se puede pisar sobre los apoyos disponibles.","Antes de mover un apoyo, el grupo comprueba que todos están seguros."],variant:"Transporta además un objeto o reduce un apoyo cuando el grupo domina el reto.",safety:"Apoyos planos y antideslizantes; quedan prohibidos los saltos largos."},
{id:39,type:"Juego cooperativo",title:"Dibujos con cuerdas",cycle:"1.º ciclo",goals:["Expresión corporal","Cooperación"],material:"Cuerdas",intensity:"Baja",duration:12,group:"Equipos de 6",color:"green",summary:"Cada equipo transforma varias cuerdas en una figura común mediante acuerdos y creatividad.",setup:"Entrega dos o tres cuerdas a cada grupo y distribuye los equipos por zonas separadas del gimnasio.",rules:["A una consigna, crean juntos una figura reconocible en el suelo.","Todas las personas deben sujetar o colocar alguna parte de la cuerda.","Al terminar, los grupos visitan las creaciones y explican cómo se organizaron."],variant:"Crea letras, figuras geométricas, animales o elementos relacionados con otra área.",safety:"Las cuerdas permanecen en el suelo y nunca se enrollan alrededor del cuerpo."},
{id:40,type:"Juego cooperativo",title:"El reto común",cycle:"3.º ciclo",goals:["Cooperación","Autonomía"],material:"Material específico",intensity:"Media",duration:18,group:"Gran grupo",color:"orange",summary:"Toda la clase encadena pequeñas misiones motrices para alcanzar un único marcador colectivo.",setup:"Prepara cuatro estaciones sencillas: pases, puntería, equilibrio y saltos de cuerda. Establece una meta global realista.",rules:["Cada logro individual suma al marcador de toda la clase.","El alumnado puede cambiar de estación y ayudar enseñando estrategias.","El reto finaliza cuando alcanzan la meta común o mejoran su marca anterior."],variant:"Deja que la clase decida la meta y distribuya el tiempo entre estaciones.",safety:"Cada estación tiene espacio propio y las ayudas se realizan sin empujar ni sujetar de forma insegura."}
);
const cooperativeFiles=["31-paracaidas-viajero.webp","32-oruga-cooperativa.webp","33-alfombra-magica.webp","34-aro-viajero.webp","35-transporte-tesoro.webp","36-pelota-no-cae.webp","37-laberinto-guiado.webp","38-puentes-rio.webp","39-dibujos-cuerdas.webp","40-reto-comun.webp"];
games.slice(30).forEach((g,i)=>g.image=`images/games/${cooperativeFiles[i]}`);
games.push(
{id:41,type:"Vuelta a la calma",title:"La bomba sentada",cycle:"1.º ciclo",goals:["Descenso progresivo","Atención"],material:"Balones",intensity:"Baja",duration:8,group:"Gran grupo",color:"blue",summary:"El balón recorre el círculo mientras una cuenta silenciosa va sentando progresivamente al grupo.",setup:"Forma un círculo de pie o sentado. Una persona en el centro, con ojos cerrados, realiza una cuenta pausada mientras el resto pasa una pelota blanda.",rules:["La persona central marca cinco fases levantando lentamente brazos y termina diciendo «bomba».","Quien tenga el balón se sienta y continúa participando pasándolo desde el suelo.","El juego termina cuando queda una sola persona de pie; todos realizan después tres respiraciones lentas."],variant:"En lugar de eliminar, quien recibe la bomba adopta una postura de estiramiento suave.",safety:"Pases cortos con las manos; nadie lanza el balón ni se desplaza corriendo."},
{id:42,type:"Vuelta a la calma",title:"El asesino del guiño",cycle:"2.º ciclo",goals:["Descenso progresivo","Percepción"],material:"Sin material",intensity:"Baja",duration:8,group:"Gran grupo",color:"green",summary:"Un juego silencioso de observación en el que quienes reciben el guiño se tumban o se sientan lentamente.",setup:"El grupo se sienta en círculo. El docente elige en secreto a quien hará los guiños y a una persona detective.",rules:["El asesino elimina mediante un guiño discreto.","Quien recibe el guiño cuenta mentalmente hasta tres y se tumba o baja la cabeza con suavidad.","El detective dispone de tres intentos para identificarlo; después se cambian los roles."],variant:"Sustituye el guiño por un pequeño gesto de manos acordado.",safety:"La eliminación se representa despacio y desde posición sentada, sin caídas bruscas."},
{id:43,type:"Vuelta a la calma",title:"La zapatilla por detrás",cycle:"1.º ciclo",goals:["Descenso progresivo","Atención"],material:"Conos",intensity:"Baja",duration:8,group:"Gran grupo",color:"orange",summary:"El grupo permanece sentado mientras una persona camina alrededor y deja discretamente un objeto.",setup:"Todos se sientan en círculo mirando al centro. Una persona camina por fuera con un cono pequeño o saquito.",rules:["Quien camina deja el objeto detrás de alguien sin detenerse.","Al descubrirlo, esa persona se levanta y lo sigue caminando deprisa, sin correr.","Si alcanza el hueco primero, intercambian los papeles; el resto permanece sentado y atento."],variant:"El perseguidor debe desplazarse a cámara lenta o siguiendo un ritmo de palmadas.",safety:"Utiliza marcha rápida, nunca carrera; círculo amplio y sin obstáculos."},
{id:44,type:"Vuelta a la calma",title:"El director de orquesta",cycle:"1.º ciclo",goals:["Calma conjunta","Imitación"],material:"Sin material",intensity:"Baja",duration:8,group:"Gran grupo",color:"yellow",summary:"El grupo copia movimientos cada vez más lentos mientras una persona intenta localizar al director.",setup:"Forma un círculo sentado. Una persona observa desde fuera mientras se elige en secreto al director.",rules:["El director inicia movimientos suaves que todo el grupo imita.","Cambia de gesto sin llamar la atención: hombros, manos, respiración o estiramientos.","El observador dispone de tres intentos para descubrirlo; después se eligen nuevos roles."],variant:"Los movimientos deben ir reduciendo amplitud hasta terminar completamente quietos.",safety:"Solo gestos articulares suaves, sin rebotes ni amplitudes forzadas."},
{id:45,type:"Vuelta a la calma",title:"El objeto escondido",cycle:"1.º ciclo",goals:["Calma conjunta","Percepción"],material:"Material específico",intensity:"Baja",duration:7,group:"Gran grupo",color:"blue",summary:"Un objeto pasa discretamente por el círculo mientras una persona intenta descubrir dónde se encuentra.",setup:"El grupo se sienta en círculo con las manos detrás. Una persona se coloca en el centro y se entrega un saquito pequeño.",rules:["El objeto se pasa despacio de mano en mano por detrás de la espalda.","Todos simulan el gesto de pasarlo para no revelar su posición.","A la señal se detiene y la persona central dispone de tres intentos para localizarlo."],variant:"Añade una segunda persona observadora o cambia el sentido sin hablar.",safety:"Objeto blando y pequeño; se entrega en la mano, nunca se lanza."},
{id:46,type:"Vuelta a la calma",title:"El teléfono gestual",cycle:"2.º ciclo",goals:["Calma conjunta","Expresión corporal"],material:"Sin material",intensity:"Baja",duration:8,group:"Equipos de 8",color:"green",summary:"Un movimiento suave viaja en silencio por una fila y se compara con el gesto original.",setup:"Forma filas sentadas mirando en la misma dirección. La última persona observa un gesto mostrado por el docente.",rules:["Cada participante toca suavemente el hombro del siguiente y representa el gesto una sola vez.","El mensaje continúa sin hablar hasta llegar a la primera persona.","Se muestran el gesto final y el inicial, valorando los cambios sin establecer ganadores."],variant:"Combina dos movimientos lentos o representa una emoción al terminar.",safety:"Toque suave en el hombro y espacio suficiente entre participantes."},
{id:47,type:"Vuelta a la calma",title:"Siete vidas tranquilas",cycle:"2.º ciclo",goals:["Descenso progresivo","Recepción"],material:"Balones",intensity:"Baja",duration:9,group:"Gran grupo",color:"orange",summary:"Una recepción pausada reduce progresivamente el grupo activo mientras quienes salen realizan recuperación consciente.",setup:"Forma un círculo amplio de pie con una pelota blanda. Cada participante comienza con una vida simbólica.",rules:["La pelota se pasa suavemente nombrando a quien debe recibirla.","Si cae por un pase adecuado, quien recibe pasa a la zona de recuperación.","En esa zona permanece sentado, respira lentamente y puede volver tras tres recepciones consecutivas del grupo."],variant:"En vez de salir, se pierde una de tres vidas y se continúa en el círculo.",safety:"Pases a la altura del pecho y sin desplazamientos rápidos."},
{id:48,type:"Vuelta a la calma",title:"La palmada viajera",cycle:"1.º ciclo",goals:["Descenso progresivo","Ritmo"],material:"Sin material",intensity:"Baja",duration:7,group:"Gran grupo",color:"yellow",summary:"Una señal rítmica recorre el círculo y los errores van reduciendo el número de participantes activos.",setup:"Todo el grupo se sienta en círculo con las manos visibles.",rules:["Una palmada envía el turno a la persona siguiente y dos cambian el sentido.","Quien se equivoca coloca las manos sobre las rodillas y pasa a observar en silencio.","Las personas observadoras ayudan a comprobar el sentido; la velocidad disminuye en cada vuelta."],variant:"Sustituye las palmadas por gestos silenciosos de cabeza o manos.",safety:"Palmadas suaves y postura sentada cómoda."},
{id:49,type:"Vuelta a la calma",title:"El guardián dormido",cycle:"1.º ciclo",goals:["Descenso progresivo","Control corporal"],material:"Material específico",intensity:"Baja",duration:8,group:"Gran grupo",color:"green",summary:"El alumnado se aproxima caminando en silencio para recuperar objetos sin despertar al guardián.",setup:"Una persona se sienta con ojos cerrados junto a varios saquitos. El resto espera detrás de una línea cercana.",rules:["De uno en uno intentan acercarse caminando, coger un objeto y regresar sin hacer ruido.","Si el guardián señala correctamente la dirección del sonido, esa persona se sienta y observa.","Quien logra recuperar un objeto se convierte en nuevo guardián."],variant:"Permite avanzar a dos personas a la vez o coloca los objetos a distintas distancias.",safety:"Solo caminar; guardián sentado y objetos blandos colocados en suelo despejado."},
{id:50,type:"Vuelta a la calma",title:"La estatua que se apaga",cycle:"1.º ciclo",goals:["Descenso progresivo","Relajación"],material:"Sin material",intensity:"Baja",duration:7,group:"Gran grupo",color:"blue",summary:"Las estatuas van sentándose al perder el equilibrio hasta que todo el grupo termina relajado.",setup:"El alumnado se distribuye de pie por el espacio con separación suficiente. El docente propone una postura sencilla.",rules:["Todos mantienen la postura mientras realizan respiraciones lentas.","Quien se mueve o pierde el equilibrio se sienta y continúa respirando en silencio.","Cada nueva postura es más sencilla y baja hasta terminar todo el grupo sentado o tumbado."],variant:"Las personas sentadas pueden proponer la siguiente estatua mediante un gesto.",safety:"Posturas estables, sin apoyo sobre una sola pierna durante demasiado tiempo ni equilibrios difíciles."}
);
const cooldownFiles=["41-bomba-sentada.webp","42-asesino-guino.webp","43-zapatilla-detras.webp","44-director-orquesta.webp","45-objeto-escondido.webp","46-telefono-gestual.webp","47-siete-vidas.webp","48-palmada-viajera.webp","49-guardian-dormido.webp","50-estatua-apaga.webp"];
games.slice(40).forEach((g,i)=>g.image=`images/games/${cooldownFiles[i]}`);

games.push(
{id:51,type:"Juego motor",title:"Pases que crecen",cycle:"1.º ciclo",goals:["Pases","Recepción"],material:"Balones",intensity:"Media",duration:10,group:"Parejas",color:"orange",summary:"Cada pareja enlaza pases seguros y aumenta poco a poco la distancia sin perder el control.",setup:"Distribuye a las parejas frente a frente, separadas dos metros y con un balón blando por pareja.",rules:["Realizan cinco pases seguidos con dos manos.","Si completan la serie, ambos retroceden un paso; si el balón cae, avanzan uno.","El reto es encontrar la mayor distancia desde la que todavía pueden pasar con precisión."],variant:"Alterna pase de pecho, picado y por encima de la cabeza, o utiliza la mano no dominante.",safety:"Parejas alineadas en calles separadas y pases siempre dirigidos al pecho."},
{id:52,type:"Juego motor",title:"El túnel rodante",cycle:"1.º ciclo",goals:["Puntería","Coordinación"],material:"Balones",intensity:"Baja",duration:8,group:"Parejas",color:"green",summary:"La pareja hace rodar el balón con precisión a través de una pequeña portería de conos.",setup:"Cada pareja coloca dos conos como portería y se sitúa a ambos lados, a unos tres metros.",rules:["Una persona hace rodar el balón intentando cruzar la portería.","La compañera lo detiene y lo devuelve por el mismo túnel.","Tras cinco aciertos, estrechan la portería o aumentan la distancia."],variant:"Recibe con una sola mano, alterna derecha e izquierda o añade una segunda portería.",safety:"El balón circula siempre por el suelo y las porterías quedan separadas de otras parejas."},
{id:53,type:"Juego motor",title:"Lanza, aplaude y atrapa",cycle:"1.º ciclo",goals:["Reacción","Recepción"],material:"Balones",intensity:"Media",duration:9,group:"Parejas",color:"yellow",summary:"Un lanzamiento controlado permite a la pareja reaccionar, aplaudir y recibir antes de que caiga el balón.",setup:"Las parejas se colocan frente a frente a corta distancia con una pelota blanda.",rules:["Quien tiene el balón lo lanza suavemente hacia arriba y hacia su pareja.","La persona receptora da una palmada antes de atraparlo.","Tras cada recepción cambian los roles y suman cuántas consiguen seguidas."],variant:"Realiza dos palmadas, toca una rodilla o gira media vuelta antes de recibir.",safety:"Lanzamientos suaves, con trayectoria alta y sin dirigir el balón a la cara."},
{id:54,type:"Juego motor",title:"El espejo con bote",cycle:"2.º ciclo",goals:["Bote","Coordinación"],material:"Balones",intensity:"Media",duration:10,group:"Parejas",color:"blue",summary:"Una persona dirige desplazamientos y cambios de mano con bote mientras su pareja imita como un espejo.",setup:"Cada integrante dispone de un balón. Las parejas ocupan cuadrados amplios y se colocan frente a frente.",rules:["La persona guía bota y se desplaza lentamente dentro de su zona.","La pareja reproduce los movimientos manteniendo el control de su balón.","A los treinta segundos cambian de rol."],variant:"Introduce cambios de altura, mano, dirección o señales para detener el bote.",safety:"Cabeza levantada, velocidad moderada y zonas amplias sin cruces entre parejas."},
{id:55,type:"Juego cooperativo",title:"Espalda con espalda",cycle:"1.º ciclo",goals:["Cooperación","Control corporal"],material:"Balones",intensity:"Baja",duration:8,group:"Parejas",color:"green",summary:"La pareja transporta un balón sujeto entre sus espaldas coordinando cada paso sin utilizar las manos.",setup:"Cada pareja coloca una pelota grande y blanda entre sus espaldas, dentro de una calle corta.",rules:["Deben llegar juntos hasta un cono sin sujetar el balón con las manos.","Si cae, se detienen, lo recolocan y continúan desde ese lugar.","Al llegar, regresan cambiando la altura a la que colocan el balón."],variant:"Realiza un pequeño recorrido curvo o transporta el balón entre hombros o costados.",safety:"Solo caminar, recorridos cortos y balones blandos de tamaño suficiente."},
{id:56,type:"Juego motor",title:"Pase bajo la cuerda",cycle:"2.º ciclo",goals:["Pases","Control de fuerza"],material:"Balones",intensity:"Media",duration:10,group:"Parejas",color:"orange",summary:"La pareja regula la fuerza para enviar el balón con un bote por debajo de una cuerda baja.",setup:"Coloca una cuerda o cinta a poca altura entre dos conos. Cada pareja se sitúa a un lado con un balón.",rules:["El pase debe dar un bote antes de cruzar por debajo de la cuerda.","La pareja recibe sin que se produzca un segundo bote.","Cada cinco pases válidos aumentan ligeramente la distancia."],variant:"Cambia la mano de pase, modifica la altura de la cuerda o marca una zona concreta de bote.",safety:"Cuerda fácilmente liberable, conos estables y prohibido saltar por encima."},
{id:57,type:"Juego motor",title:"Diana compartida",cycle:"2.º ciclo",goals:["Puntería","Cooperación"],material:"Balones",intensity:"Media",duration:12,group:"Parejas",color:"yellow",summary:"Dos compañeros combinan sus lanzamientos para superar juntos retos de precisión sobre distintas dianas.",setup:"Prepara dianas con aros, conos o cajas y entrega dos pelotas blandas a cada pareja.",rules:["Cada integrante realiza un lanzamiento antes de cambiar de diana.","La pareja suma un punto si ambos alcanzan la misma diana en la ronda.","El objetivo es completar todas las dianas, no competir con las demás parejas."],variant:"Lanza rodando, con bote previo, con la mano no dominante o desde distancias diferentes.",safety:"Las recogidas se realizan únicamente a la señal y cuando nadie está lanzando."},
{id:58,type:"Juego motor",title:"Protege tu balón",cycle:"3.º ciclo",goals:["Oposición","Control corporal"],material:"Balones",intensity:"Media",duration:10,group:"Parejas",color:"blue",summary:"Una persona protege el balón mediante la posición corporal mientras su pareja intenta tocarlo sin contacto.",setup:"Delimita círculos amplios. Una persona sostiene o controla el balón y la otra se sitúa enfrente.",rules:["La persona atacante gira y cambia de orientación para mantener el balón alejado.","La defensora suma un punto si toca el balón con la mano abierta, sin agarrar ni empujar.","A los veinte segundos cambian los roles."],variant:"Protege el balón botando o permite desplazarse dentro de un cuadrado pequeño.",safety:"Sin contacto corporal, tirones ni golpes; detener el juego si se pierde el equilibrio."},
{id:59,type:"Juego motor",title:"Pases en movimiento",cycle:"3.º ciclo",goals:["Pases","Desplazamientos"],material:"Balones",intensity:"Alta",duration:12,group:"Parejas",color:"orange",summary:"La pareja avanza coordinada por una calle de conos mientras mantiene una secuencia continua de pases.",setup:"Organiza calles de quince metros con conos. Cada pareja comienza junta en un extremo con un balón.",rules:["Avanzan en paralelo realizando pases sin detenerse.","Deben completar al menos un pase entre cada par de conos.","Al llegar, regresan cambiando el tipo de desplazamiento."],variant:"Añade pase picado, desplazamiento lateral o una finalización a una diana.",safety:"Calles suficientemente anchas y separadas; pases por delante del desplazamiento, nunca cruzados a otras zonas."},
{id:60,type:"Vuelta a la calma",title:"Pase y equilibrio",cycle:"1.º ciclo",goals:["Equilibrio","Calma conjunta"],material:"Balones",intensity:"Baja",duration:7,group:"Parejas",color:"green",summary:"Pases lentos desde posiciones de equilibrio ayudan a controlar el cuerpo y reducir progresivamente la activación.",setup:"Las parejas se colocan de rodillas o sentadas frente a frente con una pelota blanda.",rules:["Realizan pases suaves manteniendo la postura propuesta.","Antes de devolver el balón, inspiran y espiran lentamente.","Cada minuto cambian a una postura de equilibrio más cómoda y cercana al suelo."],variant:"Pasa con una mano, eleva ligeramente un pie o rueda el balón por el suelo.",safety:"Posturas estables, sin forzar articulaciones y con suficiente distancia entre parejas."}
);
const pairBallFiles=["51-pases-crecen.webp","52-tunel-rodante.webp","53-lanza-aplaude-atrapa.webp","54-espejo-bote.webp","55-espalda-espalda.webp","56-pase-cuerda.webp","57-diana-compartida.webp","58-protege-balon.webp","59-pases-movimiento.webp","60-pase-equilibrio.webp"];
games.slice(50).forEach((g,i)=>g.image=`images/games/${pairBallFiles[i]}`);

games.push(
{id:61,type:"Ritmo y percepción temporal",title:"El pulso viajero",cycle:"1.º ciclo",goals:["Ritmo","Pulsación"],material:"Material específico",intensity:"Media",duration:9,group:"Gran grupo",color:"orange",summary:"El grupo adapta pasos y palmadas a una pulsación regular que cambia progresivamente.",setup:"Distribuye al alumnado por el espacio y utiliza un pandero o tambor para marcar el pulso.",rules:["Cada golpe corresponde a un paso y cada cuatro golpes se añade una palmada.","Si el pulso se detiene, todos quedan inmóviles.","El docente alterna tempos lentos y rápidos sin cambios bruscos."],variant:"El alumnado propone movimientos para cada bloque de ocho pulsos.",safety:"Mantén separación suficiente y evita aceleraciones que provoquen carreras descontroladas."},
{id:62,type:"Ritmo y percepción temporal",title:"Estatuas a tiempo",cycle:"1.º ciclo",goals:["Reacción","Duración"],material:"Aros",intensity:"Media",duration:8,group:"Gran grupo",color:"blue",summary:"Moverse mientras dura una señal y detenerse exactamente cuando termina mejora la percepción de inicio y final.",setup:"Reparte aros por el espacio y prepara fragmentos musicales o una señal sonora.",rules:["Mientras suena la música se desplazan sin pisar los aros.","Cuando cesa, deben congelarse dentro o junto a un aro.","Antes de cada ronda se anuncia si la señal durará poco, medio o mucho tiempo."],variant:"El alumnado anticipa levantando una mano cuando cree que la señal está a punto de terminar.",safety:"Coloca suficientes aros para evitar aglomeraciones y prohíbe empujar para ocuparlos."},
{id:63,type:"Ritmo y percepción temporal",title:"Eco de palmadas",cycle:"1.º ciclo",goals:["Ritmo","Memoria motriz"],material:"Sin material",intensity:"Baja",duration:8,group:"Parejas",color:"green",summary:"Una secuencia breve de palmadas y percusión corporal viaja de una persona a su pareja como un eco.",setup:"Forma parejas frente a frente con distancia suficiente.",rules:["Una persona crea una secuencia de cuatro tiempos.","La pareja espera un pulso y la reproduce exactamente.","Tras tres secuencias cambian los roles."],variant:"Amplía a seis u ocho tiempos o combina palmadas, muslos, pies y silencios.",safety:"Golpes corporales suaves y volumen moderado para proteger la audición."},
{id:64,type:"Ritmo y percepción temporal",title:"Llegar en diez segundos",cycle:"2.º ciclo",goals:["Percepción temporal","Control de velocidad"],material:"Conos",intensity:"Media",duration:10,group:"Parejas",color:"yellow",summary:"Recorrer una distancia intentando llegar en un tiempo exacto obliga a regular conscientemente la velocidad.",setup:"Marca calles de diez a quince metros. Una persona se desplaza y su pareja controla el tiempo.",rules:["El objetivo es cruzar la meta exactamente a los diez segundos, sin reloj visible.","La pareja comunica el tiempo conseguido al finalizar.","Repiten ajustando la velocidad y después intercambian los roles."],variant:"Prueba con cinco, ocho o quince segundos y distintos tipos de desplazamiento.",safety:"Cada pareja utiliza su propia calle y frena después de la línea de llegada."},
{id:65,type:"Ritmo y percepción temporal",title:"El reloj corporal",cycle:"2.º ciclo",goals:["Percepción temporal","Expresión corporal"],material:"Aros",intensity:"Baja",duration:10,group:"Equipos de 6",color:"blue",summary:"El cuerpo representa el paso del tiempo mediante posiciones y movimientos sincronizados.",setup:"Forma relojes grandes en el suelo con aros o marcas y distribuye pequeños equipos alrededor.",rules:["Dos participantes representan las agujas con brazos o desplazamientos.","El resto mantiene una pulsación con pasos suaves.","A la señal deben representar una hora o una duración indicada."],variant:"Representa intervalos, medias horas o crea un reloj humano en movimiento continuo.",safety:"Movimientos lentos, sin tumbarse sobre otras personas ni pisar los aros."},
{id:66,type:"Ritmo y percepción temporal",title:"El balón metrónomo",cycle:"2.º ciclo",goals:["Ritmo","Pases"],material:"Balones",intensity:"Media",duration:10,group:"Equipos de 6",color:"orange",summary:"El balón recorre el círculo siguiendo una pulsación constante y obliga a anticipar el momento del pase.",setup:"Forma círculos de seis con un balón blando y marca el pulso con palmas o tambor.",rules:["Cada pase se realiza exactamente en un golpe del pulso.","Tras una vuelta completa se cambia el sentido.","Si el balón cae, se recupera sin detener la pulsación y el grupo vuelve a entrar a tiempo."],variant:"Acelera gradualmente, añade un segundo balón o deja un pulso de silencio entre pases.",safety:"Pases cortos al pecho y círculos separados entre sí."},
{id:67,type:"Ritmo y percepción temporal",title:"Lento, medio, rápido",cycle:"1.º ciclo",goals:["Control de velocidad","Ritmo"],material:"Conos",intensity:"Media",duration:9,group:"Gran grupo",color:"green",summary:"Un circuito con zonas de diferente tempo enseña a distinguir y ajustar velocidades de movimiento.",setup:"Crea un recorrido dividido en tres zonas señaladas con conos de colores.",rules:["En la primera zona se avanza lentamente, en la segunda a ritmo medio y en la tercera rápido sin correr al máximo.","El cambio de velocidad se realiza al cruzar cada línea.","En la siguiente vuelta se modifica el orden de los tempos."],variant:"Asocia cada velocidad a un ritmo de palmadas o a diferentes desplazamientos.",safety:"Deja espacio de frenado y suficiente distancia entre quienes realizan el circuito."},
{id:68,type:"Ritmo y percepción temporal",title:"Caen a la vez",cycle:"2.º ciclo",goals:["Simultaneidad","Anticipación"],material:"Material específico",intensity:"Baja",duration:10,group:"Parejas",color:"yellow",summary:"La pareja ajusta la fuerza y el momento de lanzamiento para que dos pañuelos lleguen al suelo simultáneamente.",setup:"Entrega dos pañuelos ligeros a cada pareja y distribúyelas por zonas separadas.",rules:["Cada integrante lanza un pañuelo hacia arriba desde una altura acordada.","El reto es que ambos toquen el suelo al mismo tiempo.","Después de cada intento deciden si cambiar fuerza, altura o momento de salida."],variant:"Usa pelotas de espuma, lanza desde alturas diferentes o añade una cuenta común.",safety:"Material ligero, lanzamientos verticales y mirada al frente para evitar choques."},
{id:69,type:"Ritmo y percepción temporal",title:"La comba sincronizada",cycle:"3.º ciclo",goals:["Ritmo","Cooperación"],material:"Cuerdas",intensity:"Alta",duration:12,group:"Equipos de 4",color:"orange",summary:"El equipo coordina giro, entrada y salto para mantener una secuencia rítmica compartida.",setup:"Dos participantes giran una cuerda larga y el resto espera en una zona lateral segura.",rules:["Quien entra debe hacerlo siguiendo la cuenta rítmica del equipo.","El objetivo es completar ocho saltos regulares y salir sin detener la cuerda.","Se rotan todas las funciones después de cada intento."],variant:"Entran dos personas, cambian el tempo o acompañan la secuencia con una rima.",safety:"Cuerda blanda, giro moderado y entrada únicamente cuando el espacio esté libre."},
{id:70,type:"Ritmo y percepción temporal",title:"Respiración de cuatro tiempos",cycle:"1.º ciclo",goals:["Percepción temporal","Relajación"],material:"Balones",intensity:"Baja",duration:6,group:"Parejas",color:"green",summary:"Una secuencia de respiración y movimiento lento permite percibir duraciones iguales durante la vuelta a la calma.",setup:"Las parejas se sientan o tumban cómodamente con una pelota blanda entre ambas.",rules:["Inspiran durante cuatro tiempos mientras elevan suavemente las manos.","Mantienen un tiempo y espiran durante otros cuatro mientras bajan la pelota.","Repiten sin forzar y respetando el ritmo respiratorio de cada persona."],variant:"Haz rodar lentamente el balón a la pareja durante la espiración.",safety:"No se obliga a retener el aire; quien sienta incomodidad respira con normalidad."}
);
const rhythmFiles=["61-pulso-viajero.webp","62-estatuas-tiempo.webp","63-eco-palmadas.webp","64-diez-segundos.webp","65-reloj-corporal.webp","66-balon-metronomo.webp","67-lento-medio-rapido.webp","68-caen-vez.webp","69-comba-sincronizada.webp","70-respiracion-cuatro.webp"];
games.slice(60).forEach((g,i)=>g.image=`images/games/${rhythmFiles[i]}`);

games.push(
{id:71,type:"Percepción espacial",title:"La brújula humana",cycle:"2.º ciclo",goals:["Orientación espacial","Reacción"],material:"Conos",intensity:"Media",duration:10,group:"Gran grupo",color:"blue",summary:"El alumnado orienta sus desplazamientos según puntos cardinales asociados a las zonas del espacio.",setup:"Señala norte, sur, este y oeste con cuatro conos de colores en los extremos de la pista.",rules:["Todos parten del centro y se desplazan hacia el punto nombrado.","Una segunda consigna indica cómo regresar.","Cambia la referencia inicial para comprobar si mantienen la orientación."],variant:"Combina dos direcciones o utiliza derecha, izquierda, delante y detrás.",safety:"Varias zonas de llegada y desplazamiento controlado para evitar aglomeraciones."},
{id:72,type:"Percepción espacial",title:"El laberinto por voz",cycle:"2.º ciclo",goals:["Orientación espacial","Comunicación"],material:"Conos",intensity:"Baja",duration:12,group:"Parejas",color:"green",summary:"Una persona recorre un laberinto sencillo atendiendo a las referencias espaciales de su pareja.",setup:"Construye pasillos anchos con conos; una persona guía desde fuera y otra avanza con visión limitada.",rules:["Solo se usan indicaciones verbales: avanza, gira, derecha, izquierda y detente.","Quien recorre puede parar cuando lo necesite.","Al finalizar cambian los roles."],variant:"Realiza primero el recorrido con ojos abiertos o añade puntos de paso numerados.",safety:"Sin obstáculos duros, marcha lenta y guía siempre próxima."},
{id:73,type:"Percepción espacial",title:"Dentro, fuera y alrededor",cycle:"1.º ciclo",goals:["Orientación espacial","Conceptos espaciales"],material:"Aros",intensity:"Media",duration:8,group:"Gran grupo",color:"yellow",summary:"Consignas rápidas permiten experimentar dentro, fuera, delante, detrás y alrededor de un aro.",setup:"Coloca un aro por participante con separación suficiente.",rules:["El docente nombra una relación espacial y todos la representan.","Dos palmadas significan cambiar de aro.","Las secuencias aumentan de una a tres consignas."],variant:"Trabaja por parejas con un aro o deja que el alumnado dirija una secuencia.",safety:"Aros planos, cambios de lugar sin correr y mirada al frente."},
{id:74,type:"Percepción espacial",title:"Geometría corporal",cycle:"2.º ciclo",goals:["Representación espacial","Cooperación"],material:"Cuerdas",intensity:"Baja",duration:12,group:"Equipos de 6",color:"orange",summary:"Los equipos construyen figuras geométricas ocupando y organizando el espacio con sus cuerpos.",setup:"Entrega una cuerda a cada equipo y delimita zonas amplias.",rules:["Representan la figura nombrada usando la cuerda y sus posiciones.","Todos deben formar parte del contorno o del interior.","Explican después cómo se distribuyeron."],variant:"Crea letras, simetrías, polígonos o figuras con una superficie determinada.",safety:"Cuerdas siempre en el suelo y sin enrollarlas alrededor del cuerpo."},
{id:75,type:"Percepción espacial",title:"Las cuatro zonas",cycle:"1.º ciclo",goals:["Percepción espacial","Velocidad"],material:"Conos",intensity:"Alta",duration:9,group:"Gran grupo",color:"blue",summary:"El grupo identifica y ocupa rápidamente zonas de un campo sin perder la referencia central.",setup:"Divide la pista en cuatro zonas de colores y marca claramente el centro.",rules:["Todos se desplazan alrededor del centro.","Al mostrar un color buscan esa zona sin repetir el mismo camino.","Después regresan al centro por el lateral indicado."],variant:"Nombra diagonales, zonas opuestas o dos colores consecutivos.",safety:"Distribuye varias entradas a cada zona y evita cambios de dirección bruscos."},
{id:76,type:"Percepción espacial",title:"Espejo diagonal",cycle:"2.º ciclo",goals:["Lateralidad","Orientación espacial"],material:"Sin material",intensity:"Media",duration:9,group:"Parejas",color:"green",summary:"La pareja reproduce desplazamientos laterales, diagonales y giros manteniendo una referencia común.",setup:"Las parejas se sitúan enfrentadas a ambos lados de una línea.",rules:["Una persona guía sin cruzar la línea.","La otra reproduce el movimiento como un espejo.","Cambian de rol cada treinta segundos."],variant:"Usa una cruz marcada en el suelo o incluye niveles alto, medio y bajo.",safety:"Movimientos progresivos y separación suficiente entre parejas."},
{id:77,type:"Percepción espacial",title:"La ruta secreta",cycle:"2.º ciclo",goals:["Memoria espacial","Orientación"],material:"Conos",intensity:"Media",duration:12,group:"Parejas",color:"orange",summary:"Observar, recordar y reproducir un recorrido desarrolla la memoria y organización espacial.",setup:"Crea rutas cortas con conos, aros y líneas; una persona observa mientras la otra demuestra.",rules:["La ruta se muestra una sola vez.","La pareja intenta repetir el orden y los desplazamientos.","Después comprueban juntos y cambian de función."],variant:"Añade giros, objetos que tocar o una ruta creada por el alumnado.",safety:"Obstáculos bajos, estables y suficientemente separados."},
{id:78,type:"Percepción espacial",title:"Busca el espacio libre",cycle:"3.º ciclo",goals:["Ocupación de espacios","Pases"],material:"Balones",intensity:"Alta",duration:12,group:"Equipos de 5",color:"yellow",summary:"Los jugadores se desplazan hacia espacios desocupados para ofrecer líneas de pase.",setup:"Delimita cuadrados amplios y forma grupos de cinco con un balón.",rules:["Después de pasar es obligatorio ocupar un espacio diferente.","No pueden coincidir dos personas en la misma zona marcada.","El grupo cuenta cuántos pases enlaza sin quedarse sin salida."],variant:"Añade una persona defensora o limita la recepción a espacios exteriores.",safety:"Sin contacto, balón blando y campos separados."},
{id:79,type:"Percepción espacial",title:"El mapa del gimnasio",cycle:"2.º ciclo",goals:["Representación espacial","Planificación"],material:"Aros",intensity:"Baja",duration:14,group:"Equipos de 5",color:"blue",summary:"Cada equipo representa un pequeño mapa y transforma símbolos en un recorrido real.",setup:"Entrega conos, aros y cuerdas para representar caminos, edificios y puntos de referencia.",rules:["El equipo construye su mapa en una zona.","Diseña un recorrido con salida, dos puntos de paso y meta.","Otro equipo interpreta el mapa y completa la ruta."],variant:"Dibuja primero el plano en papel o cambia la orientación del mapa.",safety:"Material plano y recorridos realizados caminando."},
{id:80,type:"Percepción espacial",title:"El tesoro orientado",cycle:"3.º ciclo",goals:["Orientación espacial","Resolución de problemas"],material:"Conos",intensity:"Media",duration:15,group:"Equipos de 4",color:"green",summary:"Un plano sencillo y referencias del entorno conducen al equipo hasta distintos tesoros.",setup:"Esconde objetos blandos y entrega planos esquemáticos con puntos de referencia.",rules:["El equipo permanece unido durante la búsqueda.","Debe visitar los puntos en el orden indicado.","En cada control anota o recuerda una clave antes de continuar."],variant:"Incluye rumbos, pasos aproximados o planos incompletos que deban completar.",safety:"Zona delimitada, sin accesos peligrosos y desplazamiento respetuoso con el entorno."},
{id:81,type:"Tradicional de Castilla y León",title:"La rana",cycle:"2.º ciclo",goals:["Puntería","Patrimonio cultural"],material:"Material específico",intensity:"Baja",duration:15,group:"Equipos de 5",color:"green",summary:"Juego tradicional de precisión en el que se lanzan fichas hacia los orificios y la boca de una rana.",setup:"Coloca una mesa de rana o adaptación escolar y marca líneas ajustadas a la edad.",rules:["Cada participante lanza cinco fichas por turno.","Cada orificio tiene un valor y la boca de la rana recibe la puntuación mayor.","Se suman los puntos del equipo tras varias rondas."],variant:"Usa saquitos o discos de goma y amplía los orificios para iniciación.",safety:"Material blando, recogida conjunta y nadie delante de la línea de lanzamiento."},
{id:82,type:"Tradicional de Castilla y León",title:"La calva",cycle:"3.º ciclo",goals:["Lanzamientos","Patrimonio cultural"],material:"Material específico",intensity:"Media",duration:15,group:"Equipos de 4",color:"orange",summary:"Adaptación del juego castellano de lanzamiento para golpear una pieza de madera colocada en el suelo.",setup:"Sitúa una calva de madera o espuma y líneas de lanzamiento progresivas.",rules:["Se lanza el marro intentando golpear directamente la calva.","Cada impacto válido suma un punto.","Después de tres lanzamientos se rota y se recoge a la señal."],variant:"Usa cilindros de espuma, aumenta el tamaño del blanco o puntúa por proximidad.",safety:"Solo material escolar blando y zona de caída completamente despejada."},
{id:83,type:"Tradicional de Castilla y León",title:"Bolo leonés",cycle:"3.º ciclo",goals:["Puntería","Patrimonio cultural"],material:"Material específico",intensity:"Media",duration:18,group:"Equipos de 5",color:"blue",summary:"Versión escolar de la modalidad leonesa de bolos, centrada en conocer su colocación y lanzamiento.",setup:"Coloca bolos ligeros inspirados en la disposición leonesa y marca una línea cercana.",rules:["Cada jugador lanza una bola para derribar el mayor número posible.","Se registra la puntuación antes de recolocar los bolos.","Todas las personas pasan por lanzar, colocar y anotar."],variant:"Simplifica la disposición o concede valor especial a un bolo señalado.",safety:"Bolos y bolas ligeros; recogida únicamente tras finalizar la tanda."},
{id:84,type:"Tradicional de Castilla y León",title:"Bolos de Pinares",cycle:"2.º ciclo",goals:["Puntería","Patrimonio cultural"],material:"Material específico",intensity:"Media",duration:18,group:"Equipos de 5",color:"yellow",summary:"Acercamiento escolar a una modalidad tradicional de la zona de Pinares mediante lanzamientos controlados.",setup:"Prepara una bolera adaptada con bolos de madera ligera o plástico y varias líneas.",rules:["Cada participante realiza un lanzamiento por ronda.","Se cuentan los bolos derribados y se reconstruye la formación.","El equipo intenta mejorar su propia marca total."],variant:"Cambia distancia, número de bolos o forma de lanzamiento según el ciclo.",safety:"Zona de lanzamiento cerrada y bolas de peso adecuado para Primaria."},
{id:85,type:"Tradicional de Castilla y León",title:"La tanga o tuta",cycle:"3.º ciclo",goals:["Puntería","Patrimonio cultural"],material:"Material específico",intensity:"Baja",duration:15,group:"Equipos de 4",color:"orange",summary:"Discos lanzados con precisión intentan derribar una pequeña pieza vertical y quedar cerca de las fichas.",setup:"Coloca una tuta ligera con fichas encima y entrega discos de goma desde una línea segura.",rules:["Cada jugador lanza dos discos.","Se puntúa al derribar la tuta y quedar más cerca de las fichas que de la pieza.","Se repone todo antes del siguiente turno."],variant:"Puntúa únicamente el derribo o usa un cono ancho como blanco.",safety:"Discos blandos y recogida solo cuando termina toda la ronda."},
{id:86,type:"Tradicional de Castilla y León",title:"La monterilla",cycle:"1.º ciclo",goals:["Puntería","Patrimonio cultural"],material:"Material específico",intensity:"Baja",duration:12,group:"Equipos de 5",color:"green",summary:"Juego tradicional de puntería adaptado para lanzar hacia una gorra o pequeño objetivo colocado en el suelo.",setup:"Coloca una gorra vieja o aro pequeño como monterilla y marca líneas próximas.",rules:["Cada participante lanza un saquito intentando dejarlo dentro o tocar el objetivo.","Se realizan tres intentos antes de rotar.","La distancia aumenta cuando el equipo logra varios aciertos."],variant:"Usa distintos tamaños de objetivo o lanza con la mano no dominante.",safety:"Saquitos blandos y lanzamientos dirigidos siempre al suelo."},
{id:87,type:"Tradicional de Castilla y León",title:"Billar romano",cycle:"3.º ciclo",goals:["Precisión","Patrimonio cultural"],material:"Material específico",intensity:"Baja",duration:18,group:"Equipos de 4",color:"blue",summary:"Juego tradicional de bolas en el que se busca aproximarse a una bola pequeña dentro de un terreno delimitado.",setup:"Marca una pista estrecha y utiliza bolas de madera ligera o petanca blanda y un boliche.",rules:["Se lanza primero el boliche y después las bolas por turnos.","Puntúa la bola que queda más próxima al objetivo.","La nueva ronda comienza desde el extremo contrario."],variant:"Introduce obstáculos suaves o asigna puntos por zonas de proximidad.",safety:"Lanzamientos rasos, pista despejada y material de peso escolar."},
{id:88,type:"Tradicional de Castilla y León",title:"Lanzamiento de herradura",cycle:"2.º ciclo",goals:["Puntería","Patrimonio cultural"],material:"Material específico",intensity:"Baja",duration:14,group:"Parejas",color:"yellow",summary:"La herradura se adapta con aros de goma que deben rodear o acercarse a una estaca baja.",setup:"Coloca estacas de plástico bajas y entrega herraduras de goma o aros pequeños.",rules:["Cada persona lanza tres veces desde la línea.","Rodear la estaca vale más que quedar cerca.","La pareja suma sus resultados y cambia de distancia."],variant:"Coloca estacas con distinta puntuación o lanza de forma rodante.",safety:"Nunca uses herraduras metálicas; estacas flexibles y zona frontal vacía."},
{id:89,type:"Tradicional de Castilla y León",title:"Lucha leonesa escolar",cycle:"3.º ciclo",goals:["Equilibrio","Patrimonio cultural"],material:"Material específico",intensity:"Media",duration:15,group:"Parejas",color:"orange",summary:"Iniciación sin derribos a la lucha leonesa mediante agarres de cinturón, equilibrio y control corporal.",setup:"Forma parejas de tamaño semejante sobre colchonetas y utiliza cinturones anchos.",rules:["Ambos mantienen el agarre acordado durante todo el reto.","Se gana un punto logrando que la pareja mueva un pie fuera del círculo, sin proyectarla.","Cada acción dura diez segundos y después se cambia de pareja."],variant:"Realiza solo juegos de desequilibrio cooperativo o empuje de manos sin cinturón.",safety:"Sin técnicas de derribo; supervisión directa, colchonetas y parada inmediata al soltar el agarre."},
{id:90,type:"Tradicional de Castilla y León",title:"Sogatira",cycle:"2.º ciclo",goals:["Fuerza cooperativa","Patrimonio cultural"],material:"Cuerdas",intensity:"Alta",duration:12,group:"2 equipos",color:"green",summary:"Dos equipos coordinan fuerza, postura y ritmo para desplazar la marca central de una cuerda.",setup:"Marca una línea central, coloca una cinta en la cuerda y forma equipos equilibrados.",rules:["Todos sujetan con ambas manos y esperan la señal.","Gana la ronda al cruzar la cinta la marca establecida.","Las rondas son breves y se reorganizan los equipos."],variant:"Sogatira sentada, por parejas o reto cooperativo de mantener la cinta centrada.",safety:"Cuerda en buen estado, sin enrollarla al cuerpo, suelo no deslizante y se detiene al oír la señal."}
);
