const warmupEquipmentFiles=["113-arana-peluda.webp","114-gavilan.webp","115-zanahoria.webp","116-muralla.webp","117-cadena-parejas.webp","118-gran-cadena.webp","119-espejo-articular.webp","120-robaconos-activo.webp","121-agrupate-activa.webp","122-sigue-guia.webp","123-islas-colchonetas.webp","124-vuelta-isla.webp","125-ambulancia.webp","126-camino-blando.webp","127-cruza-puente.webp","128-puentes-cooperativos.webp","129-bancos-refugios.webp","130-relevo-banco.webp","131-palomitas.webp","132-cambio-color.webp","133-iglu.webp","134-tiburones-socorristas.webp"];
