games.push(
{id:135,type:"Juego de calentamiento",title:"Pilla-pilla cambiante",cycle:"1.º ciclo",goals:["Activación","Reacción"],material:"Sin material",intensity:"Media",duration:8,group:"Gran grupo",color:"orange",summary:"Un pilla-pilla continuo en el que cambia quién persigue y también la forma de desplazamiento.",setup:"Delimita un espacio amplio y elige dos perseguidores claramente identificados con la mano levantada.",rules:["Los perseguidores tocan suavemente en la espalda o el hombro.","Quien es tocado pasa a perseguir y quien tocó continúa como jugador libre.","A cada señal cambia el desplazamiento: carrera suave, lateral, talones o saltos cortos."],variant:"Comienza individualmente y, por señales, juega después por parejas unidas, tríos y pequeños grupos. Al cambiar de agrupación nadie queda eliminado.",observation:"Permite regular progresivamente la intensidad y formar agrupaciones sin detener la activación.",safety:"Contacto suave, mirada al frente y espacio suficiente para frenar sin choques.",image:"images/games/113-arana-peluda.webp"},
{id:136,type:"Juego de calentamiento",title:"Pilla-pilla por parejas",cycle:"1.º ciclo",goals:["Cooperación","Desplazamientos"],material:"Sin material",intensity:"Media",duration:9,group:"Parejas",color:"blue",summary:"Las parejas se desplazan juntas mientras una pareja perseguidora intenta tocar a las demás.",setup:"Forma parejas distribuidas por el espacio. Una pareja comienza persiguiendo; todas se desplazan tomadas de una mano.",rules:["La pareja perseguidora debe mantenerse unida.","Cuando toca a otra pareja, intercambian inmediatamente sus funciones.","Las parejas pueden cambiar la mano de unión a la señal docente."],variant:"A una señal, todas las parejas se separan y buscan una persona diferente. También puede evolucionar a tríos durante una ronda.",observation:"Los cambios frecuentes evitan parejas fijas y favorecen la relación con todo el grupo.",safety:"Prohíbe tirones y giros bruscos; si una pareja se suelta debe detenerse antes de volver a unirse.",image:"images/games/117-cadena-parejas.webp"},
{id:137,type:"Juego de calentamiento",title:"Tríos fugitivos",cycle:"2.º ciclo",goals:["Cooperación","Velocidad"],material:"Sin material",intensity:"Alta",duration:10,group:"Tríos",color:"green",summary:"Los tríos huyen unidos de un perseguidor y cambian su composición cada vez que escuchan una señal.",setup:"Forma tríos unidos por los antebrazos y deja dos perseguidores libres.",rules:["Los tríos avanzan coordinados y los perseguidores tocan únicamente a quienes ocupan los extremos.","El trío tocado se detiene; uno de sus miembros pasa a perseguir y el antiguo perseguidor ocupa su lugar.","A la señal «cambio», todos se separan y forman tríos diferentes."],variant:"Alterna tríos, parejas y grupos de cuatro mediante consignas numéricas.",observation:"Antes de acelerar, deja una ronda de ensayo para coordinar los desplazamientos.",safety:"Sin arrastres ni bloqueos; reduce el campo si los perseguidores no consiguen tocar.",image:"images/games/121-agrupate-activa.webp"},
{id:138,type:"Juego de calentamiento",title:"Casas que cambian",cycle:"1.º ciclo",goals:["Percepción espacial","Reacción"],material:"Sin material",intensity:"Media",duration:9,group:"Pequeños grupos",color:"yellow",summary:"Los jugadores forman refugios humanos que cambian de tamaño mientras quienes están fuera intentan encontrar casa.",setup:"Distribuye grupos de cuatro: tres forman una casa con los brazos y uno ocupa el interior. Deja uno o dos jugadores sin casa.",rules:["Quienes no tienen casa se desplazan por el espacio.","A la señal, quienes están dentro salen y buscan una casa diferente.","Cuando se dice «mudanza», todas las casas se deshacen y se forman nuevos grupos."],variant:"Cambia la agrupación: casas de dos con un habitante, grupos de cinco o refugios de seis participantes.",observation:"No hay eliminación; quien queda fuera inicia inmediatamente la siguiente ronda.",safety:"Las casas no agarran ni cierran el paso; cambios caminando las primeras rondas.",image:"images/games/122-sigue-guia.webp"},
{id:139,type:"Juego de calentamiento",title:"Pilla-conos",cycle:"1.º ciclo",goals:["Agilidad","Reacción"],material:"Conos",intensity:"Media",duration:10,group:"Individual",color:"orange",summary:"Los conos funcionan como refugios breves y obligan a buscar continuamente nuevos espacios libres.",setup:"Reparte conos por el campo, siempre menos que participantes, y selecciona dos perseguidores.",rules:["Para salvarse se puede tocar un cono durante un máximo de tres segundos.","No se puede repetir el mismo cono dos veces seguidas.","Al ser tocado se intercambia el papel con el perseguidor."],variant:"Dos personas deben tocar juntas cada cono; después forma tríos o pequeños grupos según el color mostrado por el docente.",observation:"Retira progresivamente refugios para aumentar la movilidad o añade conos si aparecen esperas.",safety:"Conos flexibles, separados y siempre tocados con la mano, sin sentarse ni saltar sobre ellos.",image:"images/games/120-robaconos-activo.webp"},
{id:140,type:"Juego de calentamiento",title:"Colas viajeras",cycle:"2.º ciclo",goals:["Agilidad","Orientación"],material:"Material específico",intensity:"Alta",duration:10,group:"Individual",color:"blue",summary:"Cada participante protege su cinta mientras intenta conseguir otras, manteniéndose siempre en movimiento.",setup:"Cada jugador coloca una cinta o peto en la cintura, visible y fácil de extraer.",rules:["Se cogen únicamente las cintas, nunca la ropa.","Quien pierde su cola sigue jugando y puede conseguir otra.","Las colas capturadas se llevan en la mano hasta el final de la ronda."],variant:"Juega por parejas compartiendo las colas, por tríos con una cola común o por equipos que llevan las capturas a una base.",observation:"Haz rondas de uno o dos minutos y cambia las agrupaciones entre ellas.",safety:"Cintas de extracción fácil; evita agarrones, empujones y zonas demasiado estrechas.",image:"images/games/115-zanahoria.webp"},
{id:141,type:"Juego de calentamiento",title:"Balón perseguidor",cycle:"2.º ciclo",goals:["Pases","Desmarque"],material:"Balones",intensity:"Media",duration:10,group:"2 equipos",color:"green",summary:"El equipo perseguidor intenta tocar con un balón blando mediante pases, sin correr con él.",setup:"Divide la clase en dos equipos y entrega al perseguidor un balón de espuma. Delimita un campo amplio.",rules:["Quien tiene el balón no puede desplazarse y debe pasar a un compañero.","Se toca suavemente con el balón en la mano; está prohibido lanzarlo contra otra persona.","Cada toque suma un punto y la persona tocada continúa jugando."],variant:"Comienza con dos perseguidores, pasa a parejas y termina con dos equipos completos. Añade un segundo balón cuando el grupo domine el juego.",observation:"El cambio de agrupación aumenta progresivamente la necesidad de cooperar y ocupar espacios.",safety:"Solo balón de espuma; no se lanza al cuerpo y no existe contacto ni bloqueo.",image:"images/games/119-espejo-articular.webp"},
{id:142,type:"Juego de calentamiento",title:"Aros salvavidas",cycle:"1.º ciclo",goals:["Cooperación","Percepción espacial"],material:"Aros",intensity:"Media",duration:9,group:"Pequeños grupos",color:"yellow",summary:"Quienes llevan un aro pueden rescatar a los perseguidos formando agrupaciones que cambian durante el juego.",setup:"Selecciona dos perseguidores y reparte cuatro aros entre el resto del grupo.",rules:["Quien lleva un aro puede compartirlo con una persona durante tres segundos.","Después de cada rescate debe entregar el aro a otra persona.","Quien es tocado intercambia su papel con el perseguidor."],variant:"Un aro debe ser transportado por una pareja, después por un trío o por cuatro personas que cooperan para rescatar.",observation:"Asegura que los aros circulen y que nadie monopolice un refugio.",safety:"Aros siempre a la altura de la cintura o en las manos; nunca alrededor del cuello.",image:"images/games/121-agrupate-activa.webp"},
{id:143,type:"Juego de calentamiento",title:"La pelota contagiosa",cycle:"2.º ciclo",goals:["Reacción","Cooperación"],material:"Balones",intensity:"Alta",duration:10,group:"Gran grupo",color:"orange",summary:"Los perseguidores llevan una pelota blanda como distintivo y contagian mediante un toque controlado.",setup:"Dos participantes comienzan con una pelota pequeña de espuma en la mano.",rules:["Solo puede tocar quien lleva pelota y siempre con la mano libre.","La persona tocada recibe la pelota y pasa a perseguir; el anterior queda libre.","No se lanza la pelota y no se puede esconder ni retener estando quieto."],variant:"Al ser tocados, perseguidor y perseguido continúan como pareja; después se dividen en tríos o forman dos equipos.",observation:"Utiliza pelotas de colores para indicar agrupaciones diferentes en una misma ronda.",safety:"Pelotas blandas, toques suaves y prohibición de lanzar o bloquear el paso.",image:"images/games/114-gavilan.webp"},
{id:144,type:"Juego de calentamiento",title:"Cazadores por colores",cycle:"2.º ciclo",goals:["Atención","Velocidad"],material:"Material específico",intensity:"Alta",duration:12,group:"2 equipos",color:"blue",summary:"Los petos de colores determinan quién persigue y permiten reorganizar rápidamente toda la clase.",setup:"Reparte petos o cintas de cuatro colores de forma equilibrada y delimita el espacio.",rules:["El docente muestra o nombra un color; ese grupo persigue al resto durante treinta segundos.","Cada toque vale un punto colectivo y nadie queda eliminado.","Al cambiar el color, todos los roles se modifican inmediatamente."],variant:"Nombra dos colores para formar un equipo perseguidor, une colores por parejas o pide agrupaciones de tres colores distintos.",observation:"Permite variar las agrupaciones sin detener el calentamiento ni elegir siempre a los mismos perseguidores.",safety:"Toques suaves, rondas cortas y recuperación activa caminando entre señales.",image:"images/games/116-muralla.webp"}
);

const gameOverrides=JSON.parse(localStorage.getItem("ef-game-overrides")||"{}");
games.forEach((g,i)=>{if(gameOverrides[g.id])games[i]={...g,...gameOverrides[g.id],id:g.id}});
const customGames=JSON.parse(localStorage.getItem("ef-custom-games")||"[]");
games.push(...customGames);

const $=s=>document.querySelector(s), grid=$("#gameGrid"), dialog=$("#gameDialog");
let favorites=new Set(JSON.parse(localStorage.getItem("ef-favorites")||"[]")), view="all";
const norm=s=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const goals=[...new Set(games.flatMap(g=>g.goals))].sort();
goals.forEach(g=>$("#goalFilter").insertAdjacentHTML("beforeend",`<option>${g}</option>`));

function filtered(){const q=norm($("#searchInput").value),type=$("#typeFilter").value,cycle=$("#cycleFilter").value,goal=$("#goalFilter").value,material=$("#materialFilter").value,intensity=$("#intensityFilter").value;let list=games.filter(g=>(!q||norm([g.title,g.summary,g.material,...g.goals].join(" ")).includes(q))&&(!type||g.type===type)&&(!cycle||g.cycle===cycle)&&(!goal||g.goals.includes(goal))&&(!material||g.material===material)&&(!intensity||g.intensity===intensity)&&(view!=="favorites"||favorites.has(g.id)));const sort=$("#sortSelect").value;if(sort==="name")list.sort((a,b)=>a.title.localeCompare(b.title));if(sort==="duration")list.sort((a,b)=>a.duration-b.duration);return list}
function render(){const list=filtered();grid.innerHTML=list.map(g=>`<article class="game-card"><div class="card-top has-image"><img class="game-image" src="${g.image}" alt="Ilustración de ${g.title}" loading="lazy"><span class="game-number">${String(g.id).padStart(2,"0")}</span><button class="fav-btn ${favorites.has(g.id)?"saved":""}" data-fav="${g.id}" aria-label="${favorites.has(g.id)?"Quitar de":"Añadir a"} favoritos">${favorites.has(g.id)?"♥":"♡"}</button></div><div class="card-body"><div class="tags"><span class="tag">${g.type}</span><span class="tag">${g.cycle}</span><span class="tag">${g.goals[0]}</span></div><h2>${g.title}</h2><p>${g.summary}</p><div class="card-meta"><span>◷ ${g.duration} min</span><span>● ${g.intensity}</span><span>◎ ${g.group}</span></div><div class="card-actions"><button class="details-btn" data-open="${g.id}">Ver ficha completa →</button><button class="edit-game-btn" data-edit-game="${g.id}">Editar</button></div></div></article>`).join("");$("#resultCount").textContent=`${list.length} ${list.length===1?"juego":"juegos"}`;$("#favCount").textContent=favorites.size;$("#emptyState").hidden=list.length>0;grid.hidden=list.length===0;const active=[$("#searchInput"),$("#typeFilter"),$("#cycleFilter"),$("#goalFilter"),$("#materialFilter"),$("#intensityFilter")].some(e=>e.value);$("#clearBtn").hidden=!active}
function openGame(id){const g=games.find(x=>x.id===id);$("#dialogContent").innerHTML=`<img class="dialog-image" src="${g.image}" alt="Ilustración de ${g.title}"><div class="dialog-hero"><p class="eyebrow">FICHA DE JUEGO · ${g.cycle.toUpperCase()}</p><h2 id="dialogTitle">${g.title}</h2><p>${g.summary}</p><div class="dialog-meta"><span>◷ ${g.duration} minutos</span><span>● Intensidad ${g.intensity.toLowerCase()}</span><span>◎ ${g.group}</span><span>▣ ${g.material}</span></div></div><div class="dialog-body"><div class="tags">${g.goals.map(x=>`<span class="tag">${x}</span>`).join("")}</div><h3>Preparación</h3><p>${g.setup}</p><h3>Cómo se juega</h3><ol>${g.rules.map(x=>`<li>${x}</li>`).join("")}</ol><h3>Variante</h3><p>${g.variant}</p><div class="tip"><strong>Seguridad:</strong> ${g.safety}</div><div class="dialog-edit-row"><button class="edit-game-btn" data-edit-game="${g.id}">Editar esta ficha</button></div></div>`;dialog.showModal()}
function clearFilters(){["#searchInput","#typeFilter","#cycleFilter","#goalFilter","#materialFilter","#intensityFilter"].forEach(s=>$(s).value="");render()}
document.addEventListener("input",e=>{if(e.target.matches("input,select"))render()});
document.addEventListener("click",e=>{const fav=e.target.closest("[data-fav]");if(fav){const id=+fav.dataset.fav;favorites.has(id)?favorites.delete(id):favorites.add(id);localStorage.setItem("ef-favorites",JSON.stringify([...favorites]));render()}const open=e.target.closest("[data-open]");if(open)openGame(+open.dataset.open);const edit=e.target.closest("[data-edit-game]");if(edit){if(dialog.open)dialog.close();openExerciseEditor(+edit.dataset.editGame)}const nav=e.target.closest("[data-view]");if(nav){view=nav.dataset.view;document.querySelectorAll(".repository-subnav").forEach(n=>n.classList.toggle("active",n===nav));$("#viewLabel").textContent=view==="favorites"?"Mis favoritos":"Todos los recursos";render()}});
