function resizeExerciseImage(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=reject;reader.onload=()=>{const img=new Image();img.onerror=reject;img.onload=()=>{const canvas=document.createElement("canvas"),ratio=Math.max(900/img.width,600/img.height),w=img.width*ratio,h=img.height*ratio;canvas.width=900;canvas.height=600;canvas.getContext("2d").drawImage(img,(900-w)/2,(600-h)/2,w,h);resolve(canvas.toDataURL("image/webp",.78))};img.src=reader.result};reader.readAsDataURL(file)})}
function createExerciseDrawing(){const data=new FormData(exerciseForm),title=(data.get("title")||"").trim(),summary=(data.get("summary")||"").trim(),rules=(data.get("rules")||"").trim();if(!summary){$("#exerciseStatus").textContent="Escribe la descripción para crear el dibujo.";exerciseForm.elements.summary.focus();return}const text=norm([title,summary,rules,data.get("setup"),data.get("material")].join(" ")),canvas=document.createElement("canvas"),ctx=canvas.getContext("2d");canvas.width=900;canvas.height=600;const bg=ctx.createLinearGradient(0,0,900,600);bg.addColorStop(0,"#e9f4df");bg.addColorStop(1,"#b8d88c");ctx.fillStyle=bg;ctx.fillRect(0,0,900,600);ctx.strokeStyle="#ffffffcc";ctx.lineWidth=7;ctx.strokeRect(38,38,824,524);ctx.setLineDash([18,14]);ctx.beginPath();ctx.moveTo(450,40);ctx.lineTo(450,560);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle="#163d32";ctx.font="800 30px Manrope,Arial";ctx.fillText((title||"Mi ejercicio").slice(0,42),58,82);ctx.font="600 16px Arial";ctx.fillStyle="#315a4e";ctx.fillText(`${data.get("group")} · ${data.get("material")} · ${data.get("duration")} min`,58,110);const team=text.includes("equipo")||data.get("group")==="2 equipos",pairs=text.includes("parej")||data.get("group")==="Parejas",players=team?10:pairs?6:data.get("group")==="Individual"?3:8;const positions=[];for(let i=0;i<players;i++){const side=team&&i>=players/2?1:0,index=team?i%(players/2):i,cols=team?3:4,x=team?(side?575:175)+(index%cols)*72:185+(index%4)*160,y=team?190+Math.floor(index/cols)*150:190+Math.floor(index/4)*210;positions.push([x,y,side])}positions.forEach(([x,y,side],i)=>{ctx.fillStyle=side?"#2c70c9":"#ffffff";ctx.strokeStyle="#173d33";ctx.lineWidth=4;ctx.beginPath();ctx.arc(x,y,22,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle="#173d33";ctx.font="800 14px Arial";ctx.textAlign="center";ctx.fillText(String(i+1),x,y+5)});ctx.textAlign="left";const cones=text.includes("cono")||data.get("material")==="Conos",mats=text.includes("colchoneta")||data.get("material")==="Colchonetas",benches=text.includes("banco")||data.get("material")==="Bancos suecos",parachute=text.includes("paraca")||data.get("material")==="Paracaídas",ball=text.includes("balon")||text.includes("pelota")||data.get("material")==="Balones";if(cones)for(let i=0;i<5;i++){const x=280+i*85,y=300;ctx.fillStyle="#f28b28";ctx.beginPath();ctx.moveTo(x,y-24);ctx.lineTo(x-18,y+18);ctx.lineTo(x+18,y+18);ctx.closePath();ctx.fill()}if(mats)for(let i=0;i<3;i++){ctx.fillStyle=["#4b83c6","#e6a33b","#51a67a"][i];ctx.fillRect(245+i*155,275,120,70)}if(benches)for(let i=0;i<2;i++){ctx.fillStyle="#9b623b";ctx.fillRect(245+i*285,285,190,30);ctx.fillRect(260+i*285,315,15,35);ctx.fillRect(405+i*285,315,15,35)}if(parachute){const colors=["#e84c4c","#f2b83e","#3985ca","#54a47c"];colors.forEach((c,i)=>{ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(450,320);ctx.arc(450,320,115,i*Math.PI/2,(i+1)*Math.PI/2);ctx.closePath();ctx.fill()})}if(ball){ctx.fillStyle="#f1c94b";ctx.strokeStyle="#173d33";ctx.lineWidth=4;ctx.beginPath();ctx.arc(450,300,19,0,Math.PI*2);ctx.fill();ctx.stroke()}const movement=text.includes("correr")||text.includes("desplaza")||text.includes("recorrido")||text.includes("persigue")||text.includes("pilla")||text.includes("cadena");if(movement){ctx.strokeStyle="#e34b3f";ctx.lineWidth=7;ctx.setLineDash([14,10]);ctx.beginPath();ctx.moveTo(155,470);ctx.bezierCurveTo(320,390,520,535,735,435);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle="#e34b3f";ctx.beginPath();ctx.moveTo(735,435);ctx.lineTo(705,426);ctx.lineTo(716,459);ctx.closePath();ctx.fill()}ctx.fillStyle="#ffffffde";ctx.fillRect(55,510,790,55);ctx.fillStyle="#173d33";ctx.font="600 16px Arial";const caption=summary.length>94?summary.slice(0,91)+"…":summary;ctx.fillText(caption,73,543);generatedExerciseImage=canvas.toDataURL("image/webp",.82);const preview=$("#exerciseImagePreview");preview.querySelector("img").src=generatedExerciseImage;preview.hidden=false;$("#exerciseStatus").textContent="✓ Dibujo creado desde la descripción"}
