const newSession=n=>({title:`Sesión ${n}`,location:"Polideportivo",customLocation:"",objective:"",material:"",zones:{warmup:[],main:[],cooldown:[]}});
function normalizePlan(value){const clean=value&&Array.isArray(value.sessions)?value:{title:"",course:"1.º Primaria",active:0,sessions:[newSession(1)]};clean.title=clean.title||"";clean.course=clean.course||"1.º Primaria";clean.sda={timing:"",finalProduct:"",challenge:"",justification:"",competences:[],contentBlocks:[],criteria:"",contents:"",methodology:"Aprendizaje basado en retos",groupings:"",methodologicalPrinciples:"",inclusion:"",resources:"",instruments:[],indicators:"",assessmentScale:"4 niveles: inicial, en proceso, adecuado y excelente",assessmentAgents:"Heteroevaluación, autoevaluación y coevaluación",assessmentProcedure:"",...(clean.sda||{})};clean.sessions=clean.sessions.length?clean.sessions:[newSession(1)];clean.sessions.forEach((s,i)=>{s.title=s.title||`Sesión ${i+1}`;s.location=s.location||"Polideportivo";s.customLocation=s.customLocation||"";s.objective=s.objective||"";s.material=s.material||"";s.zones=s.zones||{warmup:[],main:[],cooldown:[]};["warmup","main","cooldown"].forEach(z=>s.zones[z]=Array.isArray(s.zones[z])?s.zones[z]:[])});clean.active=Math.min(Math.max(0,+clean.active||0),clean.sessions.length-1);return clean}
let plan=normalizePlan(JSON.parse(localStorage.getItem("ef-session-plan")||"null"));
function savePlan(){localStorage.setItem("ef-session-plan",JSON.stringify(plan));const state=$("#saveState");if(state){state.textContent="✓ Autoguardado en este navegador";state.classList.remove("saving")}}
