$("#sdaTabs").addEventListener("click",e=>{const button=e.target.closest("[data-sda-tab]");if(!button)return;document.querySelectorAll("[data-sda-tab]").forEach(x=>x.classList.toggle("active",x===button));document.querySelectorAll("[data-sda-panel]").forEach(x=>x.hidden=x.dataset.sdaPanel!==button.dataset.sdaTab)});
