function renderPalette(){const q=norm($("#builderSearch").value),type=$("#builderType").value,cycle=$("#builderCycle").value,material=$("#builderMaterial").value,group=$("#builderGroup").value;const groupMatch=g=>!group||g.group===group||(group==="Pequeños grupos"&&/(Equipos de|grupos|Parejas o equipos)/i.test(g.group));const list=games.filter(g=>(!q||norm(g.title+" "+g.type+" "+g.material+" "+g.group+" "+g.goals.join(" ")).includes(q))&&(!type||g.type===type)&&(!cycle||g.cycle===cycle)&&(!material||g.material===material)&&groupMatch(g));$("#builderGames").className="palette-list";$("#builderGames").innerHTML=list.map(g=>`<div class="palette-game" draggable="true" data-drag-game="${g.id}"><img src="${g.image}" alt=""><div><strong>${g.title}</strong><small>${g.duration} min · ${g.cycle}</small></div><b>⋮⋮</b></div>`).join("")}
function renderBuilder(){const s=plan.sessions[plan.active];$("#sdaTitle").value=plan.title;$("#sdaCourse").value=plan.course;$("#sessionCount").textContent=plan.sessions.length;$("#sessionTitle").value=s.title;$("#sessionLocation").value=s.location;$("#customLocationWrap").hidden=s.location!=="Otro";$("#customLocation").value=s.customLocation;$("#sessionObjective").value=s.objective;$("#sessionMaterial").value=s.material;$("#sessionTabs").innerHTML=plan.sessions.map((x,i)=>`<button class="${i===plan.active?"active":""}" data-session="${i}">Sesión ${i+1}</button>`).join("");const zones=[["warmup","Calentamiento"],["main","Parte principal"],["cooldown","Vuelta a la calma"]];$("#sessionZones").innerHTML=zones.map(([key,label])=>{const time=s.zones[key].reduce((a,x)=>a+x.minutes,0);return `<section class="session-zone" data-zone="${key}"><div class="zone-head"><h3>${label}</h3><span>${time} min</span></div><div class="zone-items">${s.zones[key].length?s.zones[key].map((x,i)=>{const g=games.find(y=>y.id===x.gameId);if(!g)return "";const variant=x.variant===undefined?g.variant:x.variant,observation=x.observation||"",extras=variant||observation;return `<div class="session-item ${extras?"":"no-extras"}" draggable="true" data-item-zone="${key}" data-item-index="${i}"><img src="${g.image}" alt="Ilustración de ${g.title}"><div class="session-item-main"><strong>${g.title}</strong><p>${g.summary}</p><div class="session-item-meta"><span>${g.type}</span><label><input type="number" min="1" max="60" value="${x.minutes}" aria-label="Minutos" data-time-zone="${key}" data-time-index="${i}" draggable="false"> min</label></div>${extras?"":`<button class="add-notes" data-add-notes="${key}" data-add-notes-index="${i}">＋ Añadir variantes u observaciones</button>`}</div>${extras?`<div class="session-item-extra"><label><span>Variantes</span><textarea data-variant-zone="${key}" data-variant-index="${i}" draggable="false">${safe(variant)}</textarea></label><label><span>Observaciones</span><textarea data-observation-zone="${key}" data-observation-index="${i}" placeholder="Anotaciones para esta sesión" draggable="false">${safe(observation)}</textarea></label></div>`:""}<button class="remove-session-game" data-remove-zone="${key}" data-remove-index="${i}" aria-label="Quitar">×</button></div>`}).join(""):`<div class="zone-empty">Suelta aquí juegos o ejercicios</div>`}</div></section>`}).join("");$("#totalTime").textContent=s.zones.warmup.concat(s.zones.main,s.zones.cooldown).reduce((a,x)=>a+x.minutes,0)+" min";renderPalette();savePlan()}
$("#builderSearch").addEventListener("input",renderPalette);$("#sdaTitle").addEventListener("input",e=>{plan.title=e.target.value;savePlan()});$("#sdaCourse").addEventListener("change",e=>{plan.course=e.target.value;savePlan()});$("#sessionTitle").addEventListener("input",e=>{plan.sessions[plan.active].title=e.target.value;savePlan()});$("#sessionLocation").addEventListener("change",e=>{plan.sessions[plan.active].location=e.target.value;$("#customLocationWrap").hidden=e.target.value!=="Otro";savePlan()});$("#customLocation").addEventListener("input",e=>{plan.sessions[plan.active].customLocation=e.target.value;savePlan()});$("#sessionObjective").addEventListener("input",e=>{plan.sessions[plan.active].objective=e.target.value;savePlan()});$("#sessionMaterial").addEventListener("input",e=>{plan.sessions[plan.active].material=e.target.value;savePlan()});
$("#addSession").onclick=()=>{plan.sessions.push(newSession(plan.sessions.length+1));plan.active=plan.sessions.length-1;renderBuilder()};
$("#calculateMaterial").onclick=()=>{const s=plan.sessions[plan.active],used=s.zones.warmup.concat(s.zones.main,s.zones.cooldown).map(x=>games.find(g=>g.id===x.gameId)?.material).filter(x=>x&&x!=="Sin material");s.material=[...new Set(used)].join(", ")||"Sin material";renderBuilder()};
$("#builderSurface").addEventListener("click",e=>{const tab=e.target.closest("[data-session]");if(tab){plan.active=+tab.dataset.session;renderBuilder()}const rm=e.target.closest("[data-remove-zone]");if(rm){plan.sessions[plan.active].zones[rm.dataset.removeZone].splice(+rm.dataset.removeIndex,1);renderBuilder()}const add=e.target.closest("[data-add-notes]");if(add){const item=plan.sessions[plan.active].zones[add.dataset.addNotes][+add.dataset.addNotesIndex],g=games.find(x=>x.id===item.gameId);item.variant=g?.variant||"";item.observation="";renderBuilder()}});
$("#builderSurface").addEventListener("input",e=>{if(e.target.matches("[data-time-zone]")){plan.sessions[plan.active].zones[e.target.dataset.timeZone][+e.target.dataset.timeIndex].minutes=Math.max(1,+e.target.value||1);savePlan()}if(e.target.matches("[data-variant-zone]")){plan.sessions[plan.active].zones[e.target.dataset.variantZone][+e.target.dataset.variantIndex].variant=e.target.value;savePlan()}if(e.target.matches("[data-observation-zone]")){plan.sessions[plan.active].zones[e.target.dataset.observationZone][+e.target.dataset.observationIndex].observation=e.target.value;savePlan()}});
let dragged=null;$("#builderSurface").addEventListener("dragstart",e=>{const p=e.target.closest("[data-drag-game]"),i=e.target.closest("[data-item-zone]");dragged=p?{gameId:+p.dataset.dragGame}:i?{from:i.dataset.itemZone,index:+i.dataset.itemIndex}:null});
$("#builderSurface").addEventListener("dragover",e=>{const z=e.target.closest("[data-zone]");if(z){e.preventDefault();z.classList.add("drag-over")}});
$("#builderSurface").addEventListener("dragleave",e=>{const z=e.target.closest("[data-zone]");if(z)z.classList.remove("drag-over")});
$("#builderSurface").addEventListener("drop",e=>{const z=e.target.closest("[data-zone]");if(!z||!dragged)return;e.preventDefault();document.querySelectorAll(".session-zone").forEach(x=>x.classList.remove("drag-over"));const target=plan.sessions[plan.active].zones[z.dataset.zone];if(dragged.gameId){const g=games.find(x=>x.id===dragged.gameId);target.push({gameId:g.id,minutes:g.duration,variant:g.variant||"",observation:g.observation||""})}else{const item=plan.sessions[plan.active].zones[dragged.from].splice(dragged.index,1)[0];target.push(item)}dragged=null;renderBuilder()});
const safe=s=>String(s||"").replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]));
const slug=s=>norm(s||"situacion-aprendizaje").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"situacion-aprendizaje";
async function savePlanToDisk(){const data=JSON.stringify({...plan,active:0,format:"repositorio-juegos-ef",version:1,savedAt:new Date().toISOString()},null,2),name=`${slug(plan.title)}.json`;try{if(window.showSaveFilePicker){const handle=await window.showSaveFilePicker({suggestedName:name,types:[{description:"Situación de Aprendizaje",accept:{"application/json":[".json"]}}]}),writer=await handle.createWritable();await writer.write(data);await writer.close()}else{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([data],{type:"application/json"}));a.download=name;a.click();URL.revokeObjectURL(a.href)}$("#saveState").textContent="✓ Copia guardada en el ordenador"}catch(err){if(err.name!=="AbortError")alert("No se pudo guardar la copia. Inténtalo de nuevo.")}}
$("#savePlanFile").onclick=savePlanToDisk;$("#openPlanFile").onclick=()=>$("#planFileInput").click();$("#planFileInput").addEventListener("change",async e=>{const file=e.target.files[0];if(!file)return;try{const value=JSON.parse(await file.text());if(!Array.isArray(value.sessions))throw new Error();plan=normalizePlan(value);savePlan();renderBuilder();renderSdaForm();$("#saveState").textContent="✓ Copia abierta y autoguardada"}catch{alert("El archivo no contiene una Situación de Aprendizaje válida.")}e.target.value=""});
function buildPrintReport(){const zoneNames={warmup:"Calentamiento",main:"Parte principal",cooldown:"Vuelta a la calma"};$("#printReport").innerHTML=`<h1>${safe(plan.title||"Situación de Aprendizaje sin título")}</h1><div class="print-meta"><strong>Curso: ${safe(plan.course)}</strong><strong>N.º de sesiones: ${plan.sessions.length}</strong></div>${plan.sessions.map((s,i)=>{const place=s.location==="Otro"?s.customLocation:s.location;const total=Object.values(s.zones).flat().reduce((n,x)=>n+x.minutes,0);return `<article class="print-session"><h2>Sesión ${i+1}. ${safe(s.title)}</h2><div class="print-meta"><span><strong>Lugar:</strong> ${safe(place||"Sin especificar")}</span><span><strong>Duración:</strong> ${total} min</span><span><strong>Objetivo:</strong> ${safe(s.objective||"Sin especificar")}</span><span><strong>Material:</strong> ${safe(s.material||"Sin especificar")}</span></div>${Object.entries(zoneNames).map(([key,label])=>`<h3>${label}</h3>${s.zones[key].length?s.zones[key].map(item=>{const g=games.find(x=>x.id===item.gameId);if(!g)return "";const variant=item.variant===undefined?g.variant:item.variant,observation=item.observation||"",extras=variant||observation;return `<div class="print-game ${extras?"":"no-extras"}"><img src="${g.image}" alt=""><div><h4>${safe(g.title)} · ${item.minutes} min</h4><p>${safe(g.summary)}</p><p><strong>Preparación:</strong> ${safe(g.setup)}</p><ol>${g.rules.map(r=>`<li>${safe(r)}</li>`).join("")}</ol><p><strong>Seguridad:</strong> ${safe(g.safety)}</p></div>${extras?`<div class="print-extra">${variant?`<p><strong>Variantes</strong><br>${safe(variant)}</p>`:""}${observation?`<p><strong>Observaciones</strong><br>${safe(observation)}</p>`:""}</div>`:""}</div>`}).join(""):`<p class="print-empty">Sin juegos asignados.</p>`}`).join("")}</article>`}).join("")}`}
function addSdaToPrint(){const s=plan.sda,firstMeta=$("#printReport .print-meta");const list=(items,labels)=>items.length?`<ul>${items.map(x=>`<li>${safe(labels?.[x]||x)}</li>`).join("")}</ul>`:"<p>Sin seleccionar.</p>";const ce={CE1:"CE1. Vida activa y saludable",CE2:"CE2. Adaptación y resolución de situaciones motrices",CE3:"CE3. Autorregulación e interacción social",CE4:"CE4. Manifestaciones de la cultura motriz",CE5:"CE5. Interacción sostenible con el entorno",CE6:"CE6. Información y tecnología aplicada"},blocks={A:"A. Vida activa y saludable",B:"B. Organización y gestión",C:"C. Resolución de problemas motrices",D:"D. Autorregulación e interacción social",E:"E. Manifestaciones de la cultura motriz",F:"F. Interacción con el entorno",G:"G. Información, digitalización y comunicación"};firstMeta.insertAdjacentHTML("afterend",`<section class="print-sda-section"><h ress=""><h2>Diseño de la Situación de Aprendizaje</h2><p><strong>Temporalización:</strong> ${safe(s.timing||"Sin especificar")}</p><p><strong>Reto:</strong> ${safe(s.challenge||"Sin especificar")}</p><p><strong>Producto final:</strong> ${safe(s.finalProduct||"Sin especificar")}</p><h3>Justificación y contexto</h3><p>${safe(s.justification||"Sin especificar")}</p><h3>Vinculación curricular</h3><strong>Competencias específicas</strong>${list(s.competences,ce)}<strong>Bloques de contenidos</strong>${list(s.contentBlocks,blocks)}<p><strong>Criterios de evaluación:</strong><br>${safe(s.criteria||"Sin especificar")}</p><p><strong>Contenidos concretos:</strong><br>${safe(s.contents||"Sin especificar")}</p><h3>Metodología y atención a la diversidad</h3><p><strong>Metodología:</strong> ${safe(s.methodology)}</p><p><strong>Agrupamientos:</strong> ${safe(s.groupings||"Sin especificar")}</p><p>${safe(s.methodologicalPrinciples||"Sin especificar")}</p><p><strong>Atención a la diversidad y DUA:</strong><br>${safe(s.inclusion||"Sin especificar")}</p><p><strong>Recursos generales:</strong> ${safe(s.resources||"Sin especificar")}</p><h3>Evaluación</h3><p><strong>Instrumentos:</strong> ${safe(s.instruments.join(", ")||"Sin seleccionar")}</p><p><strong>Indicadores de logro:</strong><br>${safe(s.indicators||"Sin especificar")}</p><p><strong>Escala:</strong> ${safe(s.assessmentScale)}</p><p><strong>Agentes:</strong> ${safe(s.assessmentAgents)}</p><p><strong>Procedimiento:</strong><br>${safe(s.assessmentProcedure||"Sin especificar")}</p></section>`) }
$("#printPlan").onclick=()=>{buildPrintReport();addSdaToPrint();$("#printReport h[ress]")?.remove();setTimeout(()=>window.print(),150)};
const sportsDialog=$("#sportsDialog"),sportsContent=$("#sportsContent"),sportsSessionSelect=$("#sportsSessionSelect");
let sportsSessionIndex=0,sportsIndex=0,sportsItems=[];
const sportsZoneNames={warmup:"Calentamiento",main:"Parte principal",cooldown:"Vuelta a la calma"};
function collectSportsItems(sessionIndex){const session=plan.sessions[sessionIndex];if(!session)return [];return Object.keys(sportsZoneNames).flatMap(zone=>session.zones[zone].map(item=>({zone,item,game:games.find(g=>g.id===item.gameId)}))).filter(entry=>entry.game)}
function renderSportsGame(){const session=plan.sessions[sportsSessionIndex];$("#sportsSessionTitle").textContent=session?.title||`Sesión ${sportsSessionIndex+1}`;if(!sportsItems.length){$("#sportsProgress").textContent="Sin ejercicios";sportsContent.innerHTML=`<div class="sports-empty"><div><span>○</span><h2>Esta sesión aún está vacía</h2><p>Añade juegos o ejercicios en Calentamiento, Parte principal o Vuelta a la calma para utilizarlos aquí.</p></div></div>`;$("#sportsPrev").disabled=true;$("#sportsNext").disabled=true;return}sportsIndex=Math.max(0,Math.min(sportsIndex,sportsItems.length-1));const {zone,item,game}=sportsItems[sportsIndex],variant=item.variant===undefined?game.variant:item.variant,observation=item.observation||game.observation||"";$("#sportsProgress").textContent=`Ejercicio ${sportsIndex+1} de ${sportsItems.length}`;sportsContent.innerHTML=`<article class="sports-game"><img class="sports-game-image" src="${game.image}" alt="Ilustración de ${safe(game.title)}"><div class="sports-game-body"><div class="sports-game-topline"><span class="sports-part ${zone}">${sportsZoneNames[zone]}</span><span class="sports-minutes">◷ ${item.minutes} min</span></div><h2 id="sportsGameTitle">${safe(game.title)}</h2><p class="sports-summary">${safe(game.summary)}</p>${game.setup?`<h3>Preparación</h3><p>${safe(game.setup)}</p>`:""}<h3>Desarrollo</h3><ol>${game.rules.map(rule=>`<li>${safe(rule)}</li>`).join("")}</ol>${variant?`<h3>Variantes</h3><p class="sports-note">${safe(variant)}</p>`:""}${observation?`<h3>Observaciones</h3><p class="sports-note">${safe(observation)}</p>`:""}${game.safety?`<h3>Seguridad</h3><p>${safe(game.safety)}</p>`:""}</div></article>`;sportsContent.scrollTop=0;$("#sportsPrev").disabled=sportsIndex===0;$("#sportsNext").disabled=sportsIndex===sportsItems.length-1}
function loadSportsSession(index){sportsSessionIndex=Number(index);sportsIndex=0;sportsItems=collectSportsItems(sportsSessionIndex);renderSportsGame()}
function openSportsMode(){sportsSessionIndex=plan.active;sportsSessionSelect.innerHTML=plan.sessions.map((session,index)=>`<option value="${index}">Sesión ${index+1} · ${safe(session.title||"Sin título")}</option>`).join("");sportsSessionSelect.value=String(sportsSessionIndex);loadSportsSession(sportsSessionIndex);sportsDialog.showModal()}
$("#sportsMode").onclick=openSportsMode;$("#sportsClose").onclick=()=>sportsDialog.close();sportsSessionSelect.onchange=e=>loadSportsSession(e.target.value);$("#sportsPrev").onclick=()=>{if(sportsIndex>0){sportsIndex--;renderSportsGame()}};$("#sportsNext").onclick=()=>{if(sportsIndex<sportsItems.length-1){sportsIndex++;renderSportsGame()}};
let sportsTouchStart=0;sportsContent.addEventListener("touchstart",event=>{sportsTouchStart=event.changedTouches[0].clientX},{passive:true});sportsContent.addEventListener("touchend",event=>{const distance=event.changedTouches[0].clientX-sportsTouchStart;if(Math.abs(distance)<65)return;if(distance<0&&sportsIndex<sportsItems.length-1)sportsIndex++;if(distance>0&&sportsIndex>0)sportsIndex--;renderSportsGame()},{passive:true});
["#builderType","#builderCycle","#builderMaterial","#builderGroup"].forEach(id=>$(id).addEventListener("change",renderPalette));
$("#savePlanFile").addEventListener("click",()=>{plan.customGames=customGames;plan.gameOverrides=gameOverrides},true);
$("#planFileInput").addEventListener("change",async e=>{const file=e.target.files[0];if(!file)return;try{const imported=JSON.parse(await file.text());if(Array.isArray(imported.customGames)){imported.customGames.forEach(g=>{const ci=customGames.findIndex(x=>x.id===g.id),gi=games.findIndex(x=>x.id===g.id);if(ci>=0)customGames[ci]=g;else customGames.push(g);if(gi>=0)games[gi]=g;else games.push(g)});localStorage.setItem("ef-custom-games",JSON.stringify(customGames))}if(imported.gameOverrides&&typeof imported.gameOverrides==="object"){Object.assign(gameOverrides,imported.gameOverrides);Object.entries(imported.gameOverrides).forEach(([id,value])=>{const i=games.findIndex(x=>x.id===+id);if(i>=0)games[i]={...games[i],...value,id:+id}});localStorage.setItem("ef-game-overrides",JSON.stringify(gameOverrides))}render();renderPalette()}catch{}});
function activatePage(){const page=["repositorio","ejercicios","sesiones","situaciones"].includes(location.hash.slice(1))?location.hash.slice(1):"repositorio";document.body.classList.remove("page-repository","page-exercises","page-sessions","page-situations");document.body.classList.add(`page-${page}`);if(exerciseDialog.open)exerciseDialog.close();if(page==="repositorio"){showRepository();$("#viewLabel").textContent=view==="favorites"?"Mis favoritos":"Todos los recursos"}else if(page==="ejercicios"){repoSections.forEach(x=>x.hidden=true);$("#builderSurface").hidden=true;editingGameId=null;exerciseForm.reset();resetExerciseImage();$("#exerciseDialogTitle").textContent="Crear mi propio ejercicio";$("#exerciseDialogIntro").textContent="La ficha quedará guardada en este dispositivo y podrá utilizarse en las sesiones.";$("#exerciseSubmit").textContent="Guardar ejercicio";$("#exerciseStatus").textContent="";exerciseDialog.show()}else{openBuilder();$("#builderPageTitle").textContent=page==="sesiones"?"Creador de Sesiones":"Creador de Situaciones de Aprendizaje";$("#builderPageIntro").textContent=page==="sesiones"?"Organiza cada sesión arrastrando juegos y ejercicios a sus tres partes.":"Diseña la situación, organiza sus sesiones y prepara la evaluación.";if(page==="sesiones"){document.querySelectorAll("[data-sda-tab]").forEach(x=>x.classList.toggle("active",x.dataset.sdaTab==="sessions"));document.querySelectorAll("[data-sda-panel]").forEach(x=>x.hidden=x.dataset.sdaPanel!=="sessions")}else{const current=document.querySelector("[data-sda-tab].active")?.dataset.sdaTab||"data";document.querySelectorAll("[data-sda-panel]").forEach(x=>x.hidden=x.dataset.sdaPanel!==current)}}document.querySelectorAll(".topbar .nav-link").forEach(x=>x.classList.toggle("active",x.id===({repositorio:"repositoryNav",ejercicios:"exerciseNav",sesiones:"sessionsNav",situaciones:"builderNav"}[page])))}
window.addEventListener("hashchange",activatePage);
render();activatePage();
